######## list.html
{% extends "base.html" %}

{% block seo %}
    {{ super()}}
    {%- if author is defined -%}
    {% include "json_ld_author.html" ignore missing%}
    {%- else -%}
    {% include "json_ld_index.html" ignore missing%}
    {%- endif -%}
{% endblock %}

{% block main %}

{%if title and current_page != "index.html" and author is not defined %}
<div class="list-title">
    <article><strong> {{ title }} </strong></article>
</div>
{% endif %}

{% if current_page == "index.html" %}

    {% if site.banner_image %}
    <div class="content-banner-image index-banner-image" style="background-image: url({{site.banner_image}});"></div>
    {% endif %}

    {% if hero is defined %}
    <div class="hero">
        <article>
            {{hero}}
        </article>
    </div>
    {% endif %}

{% endif %}

{% if author is defined %}
<div class="hero author-hero">
    <article class="h-card">
        <div class="author-hero-profile">
            <div class="author-hero-flex">
                <div class="author-hero-image">
                    <img src="{{url_for(path=author.avatar)}}" alt="{{ author.name }}" class="avatar u-photo">
                </div>
                <div class="author-hero-info">
                    <h1 class="p-name">{{author.name}}</h1>
                    <div class="author-hero-bio">
                        <p class="p-note">{{author.bio}}</p>
                    </div>
                </div>
            </div>
            {% if author.links %}
            <div class="author-hero-links">
                <ul>
                    {% for link in author.links %}
                    <li><a href="{{ url_for(path=link.1) }}" {% if link.1 is starting_with("http") %}target="_blank"{% endif %} class="u-url">{{link.0}}</a></li>
                    {% endfor %}
                </ul>
            </div>
            {% endif %}
        </div>
    </article>
</div>
{% endif %}
<div class="content-list {%if sidebar is defined %}content-list-with-sidebar{% endif %} h-feed">
    {% if title %}<h1 class="p-name" style="display: none;">{{ title }}</h1>{% endif %}
    <div class="left">
    {%- for content in content_list %}
    <article class="content-list-item h-entry">
        <h2 class="p-name" style="display: none;">{{ content.title }}</h2>
        <a class="u-url" href="{{url_for(path=content.slug ~ '.html')}}" style="display: none;"></a>
        {% if content.date %}<time class="dt-published" datetime="{{ content.date | date(format='%+') }}" style="display: none;">{{ content.date | default_date_format }}</time>{% endif %}

        <div class="content-title-wrapper">
            <h2 class="content-title"><a href="{{url_for(path=content.slug ~ '.html')}}">{{ content.title }}</a></h2>
            {%if content.pinned %}<span class="content-pin">&star;</span>{%endif%} 
        </div>
        <p class="content-excerpt p-summary">
            {% if content.description %}
            {{ content.description | replace(from='"', to="") | truncate(length=250, end=" ...") }}
            {% else %}
            {{ content.html | striptags | trim_start_matches(pat=content.title) | truncate(length=250, end=" ...") }}
            {%- endif %}
            <a class="secondary" href="{{url_for(path=content.slug ~ '.html')}}">read more &rarr;</a>
        </p>
        {% if content.date -%}
        <footer class="data-tags-footer">
            <span class="content-date"><a class="secondary" href="{{url_for(path=content.slug ~ '.html')}}">{{ content.date | default_date_format }}</a></span>
            {% if content.tags -%}
            <ul class="content-tags overflow-auto">
                {% for tag in content.tags | slice(end=3) -%}
                {% set slug = "tag-" ~ tag | trim | slugify %}
                {% set link = slug ~ ".html"%}
                <li><a href="{{url_for(path=link)}}" class="p-category">{{ tag }}</a></li>
                {%- endfor %}
            </ul>
            {%- endif %}
        </footer>
        {%- endif %}
    </article>
    {%- else -%}
    <article class="content-list-item left">
        <h2 class="content-title">No content found</h2>
        <p class="content-excerpt">
            Add some markdown content and generate the site. &rarr; <a target="_blank" href="https://marmite.blog/getting-started.html">Getting Started</a>
        </p>
    </article>
    {%- endfor %}
    {% if total_pages is defined and total_pages > 1 %}
    {% include "pagination.html" ignore missing %}
    {% endif %}
    </div>
    {%- if sidebar is defined %}
    <div class="right">
        <article>{{sidebar}}</article>
    </div>
    {%- endif %}
</div>
{% endblock %}######## group.html
{% extends "base.html" %}
{% block main %}
        <div class="list-title">
            <article><strong> {{ title }} </strong></article>
        </div>
        <article class="group-details h-feed">
            <h1 class="p-name" style="display: none;">{{ title }}</h1>
            {% for name, items in group(kind=kind) -%}
            {% if kind == "stream" and name == "draft" %}{% continue %}{% endif %}
            <details {%if loop.index == 1%}open{%endif%}>
                <summary role="button" class="outline contrast {{kind}}-group-title">{%if kind == "author" %}{% include "group_author_avatar.html" ignore missing%}{% endif %}{% if kind == "stream" %}{{ stream_display_name(stream=name) }}{% elif kind == "series" %}{{ series_display_name(series=name) }}{% else %}{{name}}{% endif %} <sup>{{items | remove_draft | length}}</sup></summary>
                <ul>
                {% for item in items | remove_draft | slice(end=10) %}
                    <li class="h-entry">
                        <a href="{{url_for(path=item.slug ~ '.html')}}" class="u-url p-name">{{item.title}}</a>
                        <small><time class="dt-published" datetime="{{ item.date | date(format='%+') }}">{{item.date | date(format="%Y-%m-%d") }}</time></small>
                    </li>
                {% endfor %}
                {% set slug = name | trim | slugify %}
                {% if kind != "stream" %}
                {% set slug = kind ~ "-" ~ slug %}
                {% endif %}
                {% set link = slug ~ ".html"%}
                <li><a href="{{url_for(path=link)}}">more &rarr;</a></li>
            </ul>
            </details>
            {%- endfor %}
        </article>
{% endblock %}
######## content.html
{% extends "base.html" %}

{% block seo %}
<meta property="og:title" content="{{content.title}}">
{% if content.description %}
<meta property="og:description" content="{{ content.description | replace(from='"', to="") | truncate(length=100, end="...") }}">
{% else %}
<meta property="og:description" content="{{ content.html | striptags | trim_start_matches(pat=content.title) | truncate(length=100, end="...") }}">
{%- endif %}
{% if content.card_image %}
<meta property="og:image" content="{{url_for(path=content.card_image, abs=true)}}">
{% elif site.card_image %}
<meta property="og:image" content="{{url_for(path=site.card_image, abs=true)}}">
{% endif %}
{% if site.url %}
<meta property="og:url" content="{{url_for(path=content.slug, abs=true)}}.html">
{% endif %}
<meta property="og:type" content="article">
<meta property="og:site_name" content="{{site.name}}">
{% if content.date %}
<meta property="article:published_time" content="{{content.date | date(format=' %+')}}">
{% endif %}
{% if site.url and content.authors %}
<meta property="article:author" content="{{url_for(path='author-' ~ content.authors.0 ~ '.html', abs=true)}}">
{% endif %}

{% include "json_ld_content.html" ignore missing%}
{% endblock %}

{% block head %}
{{ super() }}
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.10.0/styles/github.min.css" id="highlightjs-theme" />
{%if content.extra.math %}
<script type="text/x-mathjax-config">
  MathJax.Hub.Config({tex2jax: {inlineMath: [['$','$'], ['\\(','\\)']]}});
</script>
<script type="text/javascript" src="https://cdn.mathjax.org/mathjax/latest/MathJax.js?config=TeX-AMS-MML_HTMLorMML">
</script>
{% endif %}

{% endblock %}


{% block main %}

{% if content.banner_image %}
<div class="content-banner-image" style="background-image: url({{content.banner_image}});"></div>
{% endif %}

<article class="h-entry">
  <data class="p-name" value="{{ content.title }}"></data>
  <a class="u-url" href="{{url_for(path=content.slug ~ '.html')}}" style="display: none;"></a>
  {% if content.date %}
  <time class="dt-published" datetime="{{ content.date | date(format='%+') }}" style="display: none;">{{ content.date | default_date_format }}</time>
  {% endif %}

  {% if content.stream == "draft" %}
  <div class="draft-warning" style="background-color: #fff3cd; border: 1px solid #ffeaa7; border-radius: 4px; padding: 12px; margin-bottom: 20px; color: #856404;">
    <strong>⚠️ Draft Post:</strong> This post is a draft and may not be complete yet.
  </div>
  {% endif %}

  {% include "content_title.html" ignore missing %}
  {% if content.series %}
  <div class="content-series">
    <p><small>Published as part of '<a href="{{ url_for(path='series-' ~ content.series ~ '.html') }}">{{ series_display_name(series=content.series) }}</a>' series.</small></p>
  </div>
  {% endif %}
  {% if content.toc %}
  <div class="content-toc">
    <a href="#" id="toc"></a>
    <details>
    <summary>🗒️</summary>
    {{ content.toc }}
    </details>
  </div>
  {% endif %}

  <div class="content-html e-content">{{ content.html }}</div>
  {% if content.date %}
  <footer class="data-tags-footer">

    <div class="content-authors-flex">
      <div class="content-authors-full">
        {% include "content_authors.html" ignore missing %}
      </div>

      <div class="date-tags-container">
        <div class="content-date">
          {% include "content_date.html" ignore missing %}
          {% if content.stream and content.stream != "index" %}
          <div class="content-stream">
            {% set slug = content.stream | trim | slugify %}
            {% set link = slug ~ ".html"%}
            <small><a href="{{url_for(path=link)}}">{{ stream_display_name(stream=content.stream) }}</a></small>
          </div>
          {% endif %}
        </div>

        <ul class="content-tags">
          {% for tag in content.tags %}
          {% set slug = "tag-" ~ tag | trim | slugify %}
          {% set link = slug ~ ".html"%}
          <li><a href="{{url_for(path=link)}}" class="p-category">{{ tag }}</a></li>
          {% endfor %}
        </ul>
      </div>
    </div>
  </footer>
  {% endif %}
</article>

{% if site.enable_related_content and not content.series %}
{% if content.back_links %}
<article>
  Back-links
  <ul>
    {% for item in content.back_links | slice(end=10) %}
    <li><a href="{{url_for(path=item.slug ~ '.html')}}">{{item.title}}</a></li>
    {% endfor %}
  </ul>
</article>
{% endif %}

{% if content.tags %}
  {# Only the first tag for now #}
  {% set tag = content.tags[0] %}
  {% set tag_slug = tag | slugify %}
  {% set related_content = site_data.tag.map[tag_slug] %}
  {% if related_content | length > 1 %}
  <article>
    Related {{tag}} content
    <ul>
      {% for item in related_content | sort(attribute="date") | reverse | slice(end=5) %}
      {% if item.slug == content.slug or item in content.back_links %}
      {% continue %}
      {% endif %}
      <li><a href="{{url_for(path=item.slug ~ '.html')}}">{{item.title}}</a></li>
      {% endfor %}
    </ul>
  </article>
  {% endif %}
{% endif %}
{% endif %}

{% if site.show_next_prev_links and (content.previous or content.next) %}
<article>
  <nav style="display: flex; justify-content: space-between;">
    <div>
      {% if content.previous %}<a href="{{url_for(path=content.previous.slug ~ '.html')}}">← {{ content.previous.title }}</a>{% endif %}
    </div>
    <div>
      {% if content.next %}<a href="{{url_for(path=content.next.slug ~ '.html')}}">{{ content.next.title }} →</a>{% endif %}
    </div>
  </nav>
</article>
{% endif %}

{% if comments is defined %}
    <article>{{ comments }}</article>
{% elif site.extra.comments.source is defined and content.date %}
    {%include "comments.html" ignore missing %}
{% endif %}

{% if content.source_path is string and (site.publish_md or site.source_repository) %}
<article>
<div class="content-source">
  {% set source_url = source_link(content=content) %}
  {% if source_url %}
    <a href="{{url_for(path=source_url)}}" rel="nofollow">📄 View source</a>
  {% endif %}
</div>
</article>
{% endif %}


{% endblock %}

{% block tail %}
{{ super() }}
<script src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.10.0/highlight.min.js"></script>
<script>
  hljs.highlightAll();
</script>

{%if content.extra.mermaid %}
