//! Civil date/time handling: parsing, arithmetic and `strftime` formatting.
//!
//! Only the pieces the site generator needs are implemented, but the
//! `strftime` specifier set mirrors chrono's so templates behave the same.

use std::cmp::Ordering;
use std::fmt::Write as _;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DateTime {
    pub year: i32,
    pub month: u32,
    pub day: u32,
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
    pub nanos: u32,
    /// Offset from UTC in seconds.
    pub offset: i32,
}

impl PartialOrd for DateTime {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for DateTime {
    fn cmp(&self, other: &Self) -> Ordering {
        self.timestamp()
            .cmp(&other.timestamp())
            .then(self.nanos.cmp(&other.nanos))
    }
}

const MONTH_NAMES: [&str; 12] = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
];

const DAY_NAMES: [&str; 7] = [
    "Sunday",
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
];

impl DateTime {
    pub fn new(year: i32, month: u32, day: u32) -> DateTime {
        DateTime {
            year,
            month,
            day,
            hour: 0,
            minute: 0,
            second: 0,
            nanos: 0,
            offset: 0,
        }
    }

    pub fn epoch() -> DateTime {
        DateTime::new(1970, 1, 1)
    }

    /// Seconds since the Unix epoch (accounting for the stored offset).
    pub fn timestamp(&self) -> i64 {
        let days = days_from_civil(self.year, self.month, self.day);
        days * 86400
            + i64::from(self.hour) * 3600
            + i64::from(self.minute) * 60
            + i64::from(self.second)
            - i64::from(self.offset)
    }

    pub fn from_timestamp(ts: i64, offset: i32) -> DateTime {
        let local = ts + i64::from(offset);
        let mut days = local.div_euclid(86400);
        let mut rem = local.rem_euclid(86400);
        if rem < 0 {
            rem += 86400;
            days -= 1;
        }
        let (year, month, day) = civil_from_days(days);
        DateTime {
            year,
            month,
            day,
            hour: (rem / 3600) as u32,
            minute: ((rem % 3600) / 60) as u32,
            second: (rem % 60) as u32,
            nanos: 0,
            offset,
        }
    }

    pub fn weekday(&self) -> u32 {
        let days = days_from_civil(self.year, self.month, self.day);
        // 1970-01-01 was a Thursday (index 4 with Sunday = 0).
        (((days % 7) + 11) % 7) as u32
    }

    pub fn ordinal(&self) -> u32 {
        let start = days_from_civil(self.year, 1, 1);
        let now = days_from_civil(self.year, self.month, self.day);
        (now - start + 1) as u32
    }

    /// ISO 8601 week number (%V) together with the ISO year (%G).
    pub fn iso_week(&self) -> (i32, u32) {
        let weekday = (self.weekday() + 6) % 7; // Monday = 0
        let ordinal = self.ordinal() as i32;
        let week = (ordinal - weekday as i32 + 10) / 7;
        if week < 1 {
            let prev_days = if is_leap(self.year - 1) { 366 } else { 365 };
            let (_, w) = DateTime::new(self.year - 1, 12, 31).iso_week();
            let _ = prev_days;
            (self.year - 1, w)
        } else if week > 52 {
            let days_in_year = if is_leap(self.year) { 366 } else { 365 };
            if days_in_year - ordinal < 4 - weekday as i32 {
                (self.year + 1, 1)
            } else {
                (self.year, week as u32)
            }
        } else {
            (self.year, week as u32)
        }
    }

    pub fn format(&self, fmt: &str) -> String {
        let mut out = String::new();
        let chars: Vec<char> = fmt.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            if chars[i] != '%' {
                out.push(chars[i]);
                i += 1;
                continue;
            }
            i += 1;
            if i >= chars.len() {
                out.push('%');
                break;
            }
            // Optional padding modifier: `-` (none), `_` (spaces), `0` (zeros).
            let mut pad: Option<char> = None;
            if matches!(chars[i], '-' | '_' | '0') && i + 1 < chars.len() {
                pad = Some(chars[i]);
                i += 1;
            }
            let spec = chars[i];
            i += 1;
            self.format_spec(&mut out, spec, pad);
        }
        out
    }

    fn format_spec(&self, out: &mut String, spec: char, pad: Option<char>) {
        let num = |out: &mut String, value: i64, width: usize, default_pad: char| {
            let p = pad.unwrap_or(default_pad);
            match p {
                '-' => {
                    let _ = write!(out, "{value}");
                }
                '_' => {
                    let _ = write!(out, "{value:>width$}");
                }
                _ => {
                    if value < 0 {
                        let _ = write!(out, "-{:0>width$}", -value, width = width);
                    } else {
                        let _ = write!(out, "{value:0width$}");
                    }
                }
            }
        };
        match spec {
            'Y' => num(out, i64::from(self.year), 4, '0'),
            'C' => num(out, i64::from(self.year / 100), 2, '0'),
            'y' => num(out, i64::from(self.year.rem_euclid(100)), 2, '0'),
            'm' => num(out, i64::from(self.month), 2, '0'),
            'b' | 'h' => out.push_str(&MONTH_NAMES[(self.month as usize - 1).min(11)][..3]),
            'B' => out.push_str(MONTH_NAMES[(self.month as usize - 1).min(11)]),
            'd' => num(out, i64::from(self.day), 2, '0'),
            'e' => num(out, i64::from(self.day), 2, '_'),
            'a' => out.push_str(&DAY_NAMES[self.weekday() as usize][..3]),
            'A' => out.push_str(DAY_NAMES[self.weekday() as usize]),
            'w' => num(out, i64::from(self.weekday()), 1, '-'),
            'u' => num(
                out,
                i64::from(if self.weekday() == 0 { 7 } else { self.weekday() }),
                1,
                '-',
            ),
            'j' => num(out, i64::from(self.ordinal()), 3, '0'),
            'H' => num(out, i64::from(self.hour), 2, '0'),
            'k' => num(out, i64::from(self.hour), 2, '_'),
            'I' => {
                let h = self.hour % 12;
                num(out, i64::from(if h == 0 { 12 } else { h }), 2, '0');
            }
            'l' => {
                let h = self.hour % 12;
                num(out, i64::from(if h == 0 { 12 } else { h }), 2, '_');
            }
            'P' => out.push_str(if self.hour < 12 { "am" } else { "pm" }),
            'p' => out.push_str(if self.hour < 12 { "AM" } else { "PM" }),
            'M' => num(out, i64::from(self.minute), 2, '0'),
            'S' => num(out, i64::from(self.second), 2, '0'),
            'f' => {
                let _ = write!(out, "{:09}", self.nanos);
            }
            'n' => out.push('\n'),
            't' => out.push('\t'),
            '%' => out.push('%'),
            's' => {
                let _ = write!(out, "{}", self.timestamp());
            }
            'z' => out.push_str(&self.offset_string(false)),
            ':' => out.push_str(&self.offset_string(true)),
            'Z' => out.push_str(if self.offset == 0 { "UTC" } else { "" }),
            'D' => {
                let _ = write!(
                    out,
                    "{:02}/{:02}/{:02}",
                    self.month,
                    self.day,
                    self.year.rem_euclid(100)
                );
            }
            'x' => {
                let _ = write!(
                    out,
                    "{:02}/{:02}/{:02}",
                    self.month,
                    self.day,
                    self.year.rem_euclid(100)
                );
            }
            'F' => {
                let _ = write!(out, "{:04}-{:02}-{:02}", self.year, self.month, self.day);
            }
            'T' | 'X' => {
                let _ = write!(out, "{:02}:{:02}:{:02}", self.hour, self.minute, self.second);
            }
            'R' => {
                let _ = write!(out, "{:02}:{:02}", self.hour, self.minute);
            }
            'r' => {
                let h = self.hour % 12;
                let _ = write!(
                    out,
                    "{:02}:{:02}:{:02} {}",
                    if h == 0 { 12 } else { h },
                    self.minute,
                    self.second,
                    if self.hour < 12 { "AM" } else { "PM" }
                );
            }
            'c' => {
                let _ = write!(
                    out,
                    "{} {} {:2} {:02}:{:02}:{:02} {}",
                    &DAY_NAMES[self.weekday() as usize][..3],
                    &MONTH_NAMES[(self.month as usize - 1).min(11)][..3],
                    self.day,
                    self.hour,
                    self.minute,
                    self.second,
                    self.year
                );
            }
            'G' => {
                let (y, _) = self.iso_week();
                num(out, i64::from(y), 4, '0');
            }
            'V' => {
                let (_, w) = self.iso_week();
                num(out, i64::from(w), 2, '0');
            }
            'U' => {
                let w = (self.ordinal() + 6 - self.weekday()) / 7;
