pub fn now(offset: i32) -> DateTime {
    let dur = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default();
    let mut dt = DateTime::from_timestamp(dur.as_secs() as i64, offset);
    dt.nanos = dur.subsec_nanos();
    dt
}

