//! Civil date/time handling: parsing, arithmetic and `strftime` formatting.
//!
//! Only the pieces the site generator needs are implemented, but the
//! `strftime` specifier set mirrors chrono's so templates behave the same.

use std::cmp::Ordering;
use std::fmt::Write as _;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DateTime {
    pub year: i32,
    pub month: u32,
    pub day: u32,
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
    pub nanos: u32,
    /// Offset from UTC in seconds.
    pub offset: i32,
}

impl PartialOrd for DateTime {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for DateTime {
    fn cmp(&self, other: &Self) -> Ordering {
        self.timestamp()
            .cmp(&other.timestamp())
            .then(self.nanos.cmp(&other.nanos))
    }
}

const MONTH_NAMES: [&str; 12] = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
];

const DAY_NAMES: [&str; 7] = [
    "Sunday",
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
];

impl DateTime {
    pub fn new(year: i32, month: u32, day: u32) -> DateTime {
        DateTime {
            year,
            month,
            day,
            hour: 0,
            minute: 0,
            second: 0,
            nanos: 0,
            offset: 0,
        }
    }

    pub fn epoch() -> DateTime {
        DateTime::new(1970, 1, 1)
    }

    /// Seconds since the Unix epoch (accounting for the stored offset).
    pub fn timestamp(&self) -> i64 {
        let days = days_from_civil(self.year, self.month, self.day);
        days * 86400
            + i64::from(self.hour) * 3600
            + i64::from(self.minute) * 60
            + i64::from(self.second)
            - i64::from(self.offset)
    }

    pub fn from_timestamp(ts: i64, offset: i32) -> DateTime {
        let local = ts + i64::from(offset);
        let mut days = local.div_euclid(86400);
        let mut rem = local.rem_euclid(86400);
        if rem < 0 {
            rem += 86400;
            days -= 1;
        }
        let (year, month, day) = civil_from_days(days);
        DateTime {
            year,
            month,
            day,
            hour: (rem / 3600) as u32,
            minute: ((rem % 3600) / 60) as u32,
            second: (rem % 60) as u32,
            nanos: 0,
            offset,
        }
    }

    pub fn weekday(&self) -> u32 {
        let days = days_from_civil(self.year, self.month, self.day);
        // 1970-01-01 was a Thursday (index 4 with Sunday = 0).
        (((days % 7) + 11) % 7) as u32
    }

    pub fn ordinal(&self) -> u32 {
        let start = days_from_civil(self.year, 1, 1);
        let now = days_from_civil(self.year, self.month, self.day);
        (now - start + 1) as u32
    }

    /// ISO 8601 week number (%V) together with the ISO year (%G).
    pub fn iso_week(&self) -> (i32, u32) {
        let weekday = (self.weekday() + 6) % 7; // Monday = 0
        let ordinal = self.ordinal() as i32;
        let week = (ordinal - weekday as i32 + 10) / 7;
        if week < 1 {
            let prev_days = if is_leap(self.year - 1) { 366 } else { 365 };
            let (_, w) = DateTime::new(self.year - 1, 12, 31).iso_week();
            let _ = prev_days;
            (self.year - 1, w)
        } else if week > 52 {
            let days_in_year = if is_leap(self.year) { 366 } else { 365 };
            if days_in_year - ordinal < 4 - weekday as i32 {
                (self.year + 1, 1)
            } else {
                (self.year, week as u32)
            }
        } else {
            (self.year, week as u32)
        }
    }

    pub fn format(&self, fmt: &str) -> String {
        let mut out = String::new();
        let chars: Vec<char> = fmt.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            if chars[i] != '%' {
                out.push(chars[i]);
                i += 1;
                continue;
            }
            i += 1;
            if i >= chars.len() {
                out.push('%');
                break;
