            'H' => num(out, i64::from(self.hour), 2, '0'),
            'k' => num(out, i64::from(self.hour), 2, '_'),
            'I' => {
                let h = self.hour % 12;
                num(out, i64::from(if h == 0 { 12 } else { h }), 2, '0');
            }
            'l' => {
                let h = self.hour % 12;
                num(out, i64::from(if h == 0 { 12 } else { h }), 2, '_');
            }
            'P' => out.push_str(if self.hour < 12 { "am" } else { "pm" }),
            'p' => out.push_str(if self.hour < 12 { "AM" } else { "PM" }),
