//! A YAML subset parser covering everything the config files and markdown
//! front matter use: block mappings and sequences, flow collections, quoted and
//! plain scalars, block scalars, comments and anchors.

use crate::value::{Map, Value};

pub fn parse(input: &str) -> Result<Value, String> {
    let lines = Lines::new(input);
    let mut parser = Parser { lines, pos: 0 };
    parser.skip_blank();
    if parser.pos >= parser.lines.items.len() {
        return Ok(Value::Null);
    }
    let value = parser.parse_block(parser.lines.items[parser.pos].indent)?;
    Ok(value)
}

#[derive(Debug, Clone)]
struct Line {
    indent: usize,
    content: String,
    raw: String,
}

struct Lines {
    items: Vec<Line>,
}

impl Lines {
    fn new(input: &str) -> Lines {
        let mut items = Vec::new();
        for raw in input.split('\n') {
            let raw = raw.strip_suffix('\r').unwrap_or(raw);
            let indent = raw.len() - raw.trim_start_matches(' ').len();
            let content = raw[indent..].to_string();
            items.push(Line {
                indent,
                content,
                raw: raw.to_string(),
            });
        }
        // Trailing empty line from the final newline is not meaningful.
        while items.last().map(|l| l.content.trim().is_empty()) == Some(true) {
            items.pop();
        }
        Lines { items }
    }
}

struct Parser {
    lines: Lines,
    pos: usize,
}

fn is_ignorable(content: &str) -> bool {
    let t = content.trim();
    t.is_empty() || t.starts_with('#') || t == "---" || t == "..."
}

impl Parser {
    fn skip_blank(&mut self) {
        while self.pos < self.lines.items.len() && is_ignorable(&self.lines.items[self.pos].content)
        {
            self.pos += 1;
        }
    }

    fn parse_block(&mut self, indent: usize) -> Result<Value, String> {
        self.skip_blank();
        if self.pos >= self.lines.items.len() {
            return Ok(Value::Null);
        }
        let line = self.lines.items[self.pos].clone();
        if line.indent < indent {
            return Ok(Value::Null);
        }
        if line.content.starts_with("- ") || line.content == "-" {
            self.parse_sequence(line.indent)
        } else {
            self.parse_mapping(line.indent)
        }
    }

    fn parse_sequence(&mut self, indent: usize) -> Result<Value, String> {
        let mut items = Vec::new();
        loop {
            self.skip_blank();
            if self.pos >= self.lines.items.len() {
                break;
            }
            let line = self.lines.items[self.pos].clone();
            if line.indent != indent || !(line.content.starts_with("- ") || line.content == "-") {
                if line.indent < indent {
                    break;
                }
                if !(line.content.starts_with("- ") || line.content == "-") {
                    break;
                }
                break;
            }
            let rest = if line.content == "-" {
                String::new()
            } else {
                line.content[2..].to_string()
            };
            self.pos += 1;
            if rest.trim().is_empty() {
                // Nested block on following lines.
                self.skip_blank();
                if self.pos < self.lines.items.len() && self.lines.items[self.pos].indent > indent {
                    let child_indent = self.lines.items[self.pos].indent;
                    items.push(self.parse_block(child_indent)?);
                } else {
                    items.push(Value::Null);
                }
            } else if let Some(key_end) = mapping_key_end(&rest) {
                // Inline mapping start: `- key: value`
                let child_indent = indent + 2;
                let mut map = Map::new();
                let key = unquote_key(&rest[..key_end]);
                let value_text = rest[key_end + 1..].trim().to_string();
                let value = self.parse_value_for_key(&value_text, child_indent)?;
                map.insert(key, value);
                self.parse_mapping_into(&mut map, indent + 2)?;
                items.push(Value::Map(map));
            } else {
                items.push(self.scalar_or_block(&rest, indent + 2)?);
            }
        }
        Ok(Value::Array(items))
    }

    fn parse_mapping(&mut self, indent: usize) -> Result<Value, String> {
        let mut map = Map::new();
        self.parse_mapping_into(&mut map, indent)?;
        Ok(Value::Map(map))
    }

    fn parse_mapping_into(&mut self, map: &mut Map, indent: usize) -> Result<(), String> {
        loop {
            self.skip_blank();
            if self.pos >= self.lines.items.len() {
                break;
            }
            let line = self.lines.items[self.pos].clone();
            if line.indent < indent {
                break;
            }
            if line.indent > indent {
                // Unexpected deeper indentation; treat as end of this mapping.
                break;
            }
            if line.content.starts_with("- ") || line.content == "-" {
                break;
            }
            let Some(key_end) = mapping_key_end(&line.content) else {
                break;
            };
            let key = unquote_key(&line.content[..key_end]);
            let value_text = line.content[key_end + 1..].trim().to_string();
            self.pos += 1;
            let value = self.parse_value_for_key(&value_text, indent)?;
            map.insert(key, value);
        }
        Ok(())
    }

    fn parse_value_for_key(&mut self, text: &str, indent: usize) -> Result<Value, String> {
        if text.is_empty() || text.starts_with('#') {
            // Value is a nested block (or null).
            let save = self.pos;
            self.skip_blank();
            if self.pos < self.lines.items.len() {
                let next = &self.lines.items[self.pos];
                if next.indent > indent
                    || (next.indent == indent
                        && (next.content.starts_with("- ") || next.content == "-"))
                {
                    let child_indent = next.indent;
                    return self.parse_block(child_indent);
                }
            }
            self.pos = save;
            return Ok(Value::Null);
        }
        self.scalar_or_block(text, indent)
    }

    fn scalar_or_block(&mut self, text: &str, indent: usize) -> Result<Value, String> {
        let trimmed = text.trim_end();
        if trimmed.starts_with('|') || trimmed.starts_with('>') {
            return Ok(Value::Str(self.read_block_scalar(trimmed, indent)?));
        }
        if trimmed.starts_with('&') {
            // Anchor definition: skip the anchor name and parse the remainder.
            let rest = trimmed.splitn(2, ' ').nth(1).unwrap_or("").trim().to_string();
            return self.parse_value_for_key(&rest, indent);
        }
        if trimmed.starts_with('[') || trimmed.starts_with('{') {
            return parse_flow(trimmed);
        }
        // Plain scalars may continue over following more-indented lines.
        if !trimmed.starts_with('"') && !trimmed.starts_with('\'') {
            let mut acc = strip_comment(trimmed).trim_end().to_string();
            let mut lookahead = self.pos;
            let mut extra = Vec::new();
            while lookahead < self.lines.items.len() {
                let l = &self.lines.items[lookahead];
                if l.content.trim().is_empty() {
                    break;
                }
                if l.indent <= indent {
                    break;
                }
                if mapping_key_end(&l.content).is_some()
                    || l.content.starts_with("- ")
                    || l.content.trim().starts_with('#')
                {
                    break;
                }
                extra.push(l.content.trim().to_string());
                lookahead += 1;
            }
            if !extra.is_empty() {
                self.pos = lookahead;
                for part in extra {
                    acc.push(' ');
                    acc.push_str(&part);
                }
            }
            return Ok(scalar_value(&acc));
        }
        Ok(Value::Str(unquote(trimmed)))
    }

    fn read_block_scalar(&mut self, header: &str, indent: usize) -> Result<String, String> {
        let folded = header.starts_with('>');
        let chomp = if header.contains('-') {
            Chomp::Strip
        } else if header.contains('+') {
            Chomp::Keep
        } else {
            Chomp::Clip
        };
        let explicit_indent: Option<usize> = header
            .chars()
            .filter(|c| c.is_ascii_digit())
            .next()
            .and_then(|c| c.to_digit(10))
            .map(|d| indent + d as usize);
        let mut block: Vec<String> = Vec::new();
        let mut base = explicit_indent;
        while self.pos < self.lines.items.len() {
            let line = &self.lines.items[self.pos];
            if line.content.trim().is_empty() {
                block.push(String::new());
                self.pos += 1;
                continue;
            }
            if line.indent <= indent {
                break;
            }
            let b = *base.get_or_insert(line.indent);
            let raw = &line.raw;
            let text = if raw.len() >= b { raw[b..].to_string() } else { raw.trim_start().to_string() };
            block.push(text);
            self.pos += 1;
        }
        while block.last().map(|l| l.is_empty()) == Some(true) {
            block.pop();
        }
        let mut out = String::new();
        if folded {
            let mut first = true;
            let mut prev_blank = false;
            for line in &block {
                if line.is_empty() {
                    out.push('\n');
                    prev_blank = true;
                    continue;
                }
                if first {
                    first = false;
                } else if !prev_blank {
                    out.push(' ');
                }
                prev_blank = false;
                out.push_str(line);
            }
        } else {
            for line in &block {
                out.push_str(line);
                out.push('\n');
            }
        }
        match chomp {
            Chomp::Strip => {
                while out.ends_with('\n') {
                    out.pop();
                }
            }
            Chomp::Clip => {
                while out.ends_with("\n\n") {
                    out.pop();
                }
                if folded && !out.ends_with('\n') {
                    out.push('\n');
                }
            }
            Chomp::Keep => {}
        }
        Ok(out)
    }
}

enum Chomp {
    Strip,
    Clip,
    Keep,
}

/// Find the byte index of the `:` that separates a mapping key from its value,
/// or `None` when the line is not a mapping entry.
fn mapping_key_end(content: &str) -> Option<usize> {
    let bytes = content.as_bytes();
    let mut i = 0;
    let mut quote: Option<u8> = None;
    let mut depth = 0usize;
    while i < bytes.len() {
        let c = bytes[i];
        match quote {
            Some(q) => {
                if c == q {
                    quote = None;
                } else if c == b'\\' && q == b'"' {
                    i += 1;
                }
            }
            None => match c {
                b'"' | b'\'' => quote = Some(c),
                b'[' | b'{' => depth += 1,
                b']' | b'}' => depth = depth.saturating_sub(1),
                b':' if depth == 0 => {
                    let next = bytes.get(i + 1).copied();
                    if next.is_none() || next == Some(b' ') || next == Some(b'\t') {
                        return Some(i);
                    }
                }
                b'#' if depth == 0 && i > 0 && bytes[i - 1] == b' ' => return None,
                _ => {}
            },
        }
        i += 1;
    }
    None
}

fn unquote_key(key: &str) -> String {
    unquote(key.trim())
}

fn unquote(text: &str) -> String {
    let text = text.trim();
    if text.len() >= 2 && text.starts_with('"') && text.ends_with('"') {
        return unescape_double(&text[1..text.len() - 1]);
    }
    if text.len() >= 2 && text.starts_with('\'') && text.ends_with('\'') {
        return text[1..text.len() - 1].replace("''", "'");
    }
    text.to_string()
}

fn unescape_double(text: &str) -> String {
    let mut out = String::new();
    let mut chars = text.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            Some('n') => out.push('\n'),
            Some('t') => out.push('\t'),
            Some('r') => out.push('\r'),
            Some('0') => out.push('\0'),
            Some('"') => out.push('"'),
            Some('\\') => out.push('\\'),
            Some('u') => {
                let hex: String = chars.by_ref().take(4).collect();
                if let Ok(cp) = u32::from_str_radix(&hex, 16) {
                    out.push(char::from_u32(cp).unwrap_or('\u{fffd}'));
                }
            }
            Some(other) => out.push(other),
            None => out.push('\\'),
        }
    }
    out
}

fn strip_comment(text: &str) -> &str {
    let bytes = text.as_bytes();
    let mut quote: Option<u8> = None;
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        match quote {
            Some(q) => {
                if c == q {
                    quote = None;
                }
            }
            None => match c {
                b'"' | b'\'' => quote = Some(c),
                b'#' if i == 0 || bytes[i - 1] == b' ' || bytes[i - 1] == b'\t' => {
                    return &text[..i];
                }
                _ => {}
            },
        }
        i += 1;
    }
    text
}

fn scalar_value(text: &str) -> Value {
    let t = text.trim();
    if t.is_empty() {
        return Value::Null;
    }
    if t.starts_with('"') || t.starts_with('\'') {
        return Value::Str(unquote(t));
    }
    match t {
        "null" | "Null" | "NULL" | "~" => return Value::Null,
        "true" | "True" | "TRUE" | "yes" | "Yes" | "YES" | "on" | "On" | "ON" => {
            return Value::Bool(true)
        }
        "false" | "False" | "FALSE" | "no" | "No" | "NO" | "off" | "Off" | "OFF" => {
            return Value::Bool(false)
        }
        _ => {}
    }
    if let Ok(i) = t.parse::<i64>() {
        // Leading zeros keep the string form (e.g. version numbers, zip codes).
        if !(t.len() > 1 && (t.starts_with('0') || t.starts_with("-0"))) {
            return Value::Int(i);
        }
    }
    if let Ok(f) = t.parse::<f64>() {
        if t.contains('.') || t.contains('e') || t.contains('E') {
            return Value::Float(f);
        }
    }
    Value::Str(t.to_string())
}

fn parse_flow(text: &str) -> Result<Value, String> {
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;
    let value = parse_flow_value(&chars, &mut i)?;
    Ok(value)
}

fn parse_flow_value(chars: &[char], i: &mut usize) -> Result<Value, String> {
    skip_flow_ws(chars, i);
    match chars.get(*i) {
        Some('[') => {
            *i += 1;
            let mut items = Vec::new();
            loop {
                skip_flow_ws(chars, i);
                if chars.get(*i) == Some(&']') {
                    *i += 1;
                    break;
                }
                items.push(parse_flow_value(chars, i)?);
                skip_flow_ws(chars, i);
                match chars.get(*i) {
                    Some(',') => *i += 1,
                    Some(']') => {
                        *i += 1;
                        break;
                    }
                    None => break,
                    Some(c) => return Err(format!("unexpected `{c}` in flow sequence")),
                }
            }
            Ok(Value::Array(items))
        }
        Some('{') => {
            *i += 1;
            let mut map = Map::new();
            loop {
                skip_flow_ws(chars, i);
                if chars.get(*i) == Some(&'}') {
                    *i += 1;
                    break;
                }
                let key = parse_flow_scalar(chars, i, &[':', ',', '}']);
                skip_flow_ws(chars, i);
                let mut value = Value::Null;
                if chars.get(*i) == Some(&':') {
                    *i += 1;
                    value = parse_flow_value(chars, i)?;
                }
                map.insert(unquote(key.trim()), value);
                skip_flow_ws(chars, i);
                match chars.get(*i) {
                    Some(',') => *i += 1,
                    Some('}') => {
                        *i += 1;
                        break;
                    }
                    None => break,
                    Some(c) => return Err(format!("unexpected `{c}` in flow mapping")),
                }
            }
            Ok(Value::Map(map))
        }
        _ => {
            let raw = parse_flow_scalar(chars, i, &[',', ']', '}']);
            Ok(scalar_value(raw.trim()))
        }
    }
}

fn parse_flow_scalar(chars: &[char], i: &mut usize, stops: &[char]) -> String {
    skip_flow_ws(chars, i);
    let mut out = String::new();
    if matches!(chars.get(*i), Some('"') | Some('\'')) {
        let quote = chars[*i];
        out.push(quote);
        *i += 1;
        while let Some(&c) = chars.get(*i) {
            out.push(c);
            *i += 1;
            if c == quote {
                break;
            }
        }
        return out;
    }
    while let Some(&c) = chars.get(*i) {
        if stops.contains(&c) {
            break;
        }
        out.push(c);
        *i += 1;
    }
    out
}

fn skip_flow_ws(chars: &[char], i: &mut usize) {
    while matches!(chars.get(*i), Some(' ') | Some('\t') | Some('\n') | Some('\r')) {
        *i += 1;
    }
}

/// Split YAML front matter from a markdown document body.
///
/// Returns `(front_matter, body)`.
pub fn split_front_matter(text: &str) -> (Option<String>, String) {
    let normalized = text.strip_prefix('\u{feff}').unwrap_or(text);
    let mut rest = normalized;
    // Leading blank lines are allowed before the delimiter.
    let mut leading = 0usize;
    for line in normalized.split_inclusive('\n') {
        if line.trim().is_empty() {
            leading += line.len();
        } else {
            break;
        }
    }
    rest = &normalized[leading..];
    let first_line_end = rest.find('\n').map_or(rest.len(), |i| i + 1);
    let first_line = rest[..first_line_end].trim_end();
    if first_line.trim_end() != "---" {
        return (None, normalized.to_string());
    }
    let after = &rest[first_line_end..];
    let mut offset = 0usize;
    for line in after.split_inclusive('\n') {
        let trimmed = line.trim_end();
        if trimmed == "---" || trimmed == "..." {
            let fm = after[..offset].to_string();
            let body = &after[offset + line.len()..];
            return (Some(fm), body.to_string());
        }
        offset += line.len();
    }
    (None, normalized.to_string())
}

