//! Command line parsing, mirroring the reference CLI (a clap-derived parser).

use std::collections::HashMap;

#[derive(Debug, Default, Clone)]
pub struct Cli {
    pub input_folder: String,
    pub output_folder: Option<String>,
    pub verbose: u8,
    pub watch: bool,
    pub serve: bool,
    pub bind: String,
    pub config: String,
    pub init_templates: bool,
    pub start_theme: Option<String>,
    pub set_theme: Option<String>,
    pub generate_config: bool,
    pub init_site: bool,
    pub force: bool,
    pub shortcodes: bool,
    pub show_urls: bool,
    pub new: Option<String>,
    pub edit: bool,
    pub page: bool,
    pub tags: Option<String>,
    /// Site option overrides, keyed by the long flag name.
    pub overrides: HashMap<String, String>,
}

/// Long options that take a value and map onto configuration keys.
pub const VALUE_OPTIONS: &[(&str, &str)] = &[
    ("name", "NAME"),
    ("tagline", "TAGLINE"),
    ("url", "URL"),
    ("https", "HTTPS"),
    ("footer", "FOOTER"),
    ("language", "LANGUAGE"),
    ("pagination", "PAGINATION"),
    ("enable-search", "ENABLE_SEARCH"),
    ("enable-related-content", "ENABLE_RELATED_CONTENT"),
    ("content-path", "CONTENT_PATH"),
    ("templates-path", "TEMPLATES_PATH"),
    ("static-path", "STATIC_PATH"),
    ("media-path", "MEDIA_PATH"),
    ("default-date-format", "DEFAULT_DATE_FORMAT"),
    ("colorscheme", "COLORSCHEME"),
    ("toc", "TOC"),
    ("json-feed", "JSON_FEED"),
    ("show-next-prev-links", "SHOW_NEXT_PREV_LINKS"),
    ("publish-md", "PUBLISH_MD"),
    ("source-repository", "SOURCE_REPOSITORY"),
    ("image-provider", "IMAGE_PROVIDER"),
    ("theme", "THEME"),
    ("build-sitemap", "BUILD_SITEMAP"),
    ("publish-urls-json", "PUBLISH_URLS_JSON"),
    ("enable-shortcodes", "ENABLE_SHORTCODES"),
    ("shortcode-pattern", "SHORTCODE_PATTERN"),
    ("skip-image-resize", "SKIP_IMAGE_RESIZE"),
];

/// Options whose value must be `true` or `false`.
pub const BOOL_OPTIONS: &[&str] = &[
    "https",
    "enable-search",
    "enable-related-content",
    "toc",
    "json-feed",
    "show-next-prev-links",
    "publish-md",
    "build-sitemap",
    "publish-urls-json",
    "enable-shortcodes",
    "skip-image-resize",
];

pub enum ParseOutcome {
    Run(Cli),
    Help,
    Version,
    Error(String),
}

fn value_option_meta(name: &str) -> Option<&'static str> {
    VALUE_OPTIONS
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, meta)| *meta)
}

pub fn parse<I: IntoIterator<Item = String>>(args: I) -> ParseOutcome {
    let mut cli = Cli {
        bind: "0.0.0.0:8000".to_string(),
        config: "marmite.yaml".to_string(),
        ..Default::default()
    };
    let args: Vec<String> = args.into_iter().collect();
    let mut positional: Vec<String> = Vec::new();
    let mut i = 0;
    let mut only_positional = false;

    while i < args.len() {
        let arg = args[i].clone();
        i += 1;
        if only_positional {
            positional.push(arg);
            continue;
        }
        if arg == "--" {
            only_positional = true;
            continue;
        }
        if let Some(long) = arg.strip_prefix("--") {
            let (name, inline) = match long.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (long.to_string(), None),
            };
            match name.as_str() {
                "help" => return ParseOutcome::Help,
                "version" => return ParseOutcome::Version,
                "verbose" => cli.verbose = cli.verbose.saturating_add(1),
                "watch" => cli.watch = true,
                "serve" => cli.serve = true,
                "init-templates" => cli.init_templates = true,
                "generate-config" => cli.generate_config = true,
                "init-site" => cli.init_site = true,
                "force" => cli.force = true,
                "shortcodes" => cli.shortcodes = true,
                "show-urls" => cli.show_urls = true,
                "bind" | "config" | "start-theme" | "set-theme" | "new" => {
                    let meta = match name.as_str() {
                        "bind" => "BIND",
                        "config" => "CONFIG",
                        "start-theme" => "START_THEME",
                        "set-theme" => "SET_THEME",
                        _ => "NEW",
                    };
                    let value = match take_value(inline, &args, &mut i) {
                        Some(v) => v,
                        None => return ParseOutcome::Error(missing_value(&name, meta)),
                    };
                    match name.as_str() {
                        "bind" => cli.bind = value,
                        "config" => cli.config = value,
                        "start-theme" => cli.start_theme = Some(value),
                        "set-theme" => cli.set_theme = Some(value),
                        _ => cli.new = Some(value),
                    }
                }
                other => {
                    if let Some(meta) = value_option_meta(other) {
                        let value = match take_value(inline, &args, &mut i) {
                            Some(v) => v,
                            None => return ParseOutcome::Error(missing_value(other, meta)),
                        };
                        if BOOL_OPTIONS.contains(&other) && value != "true" && value != "false" {
                            return ParseOutcome::Error(invalid_bool(other, meta, &value));
                        }
                        cli.overrides.insert(other.to_string(), value);
                    } else {
                        return ParseOutcome::Error(unexpected(&arg));
                    }
                }
            }
            continue;
        }
        if arg.len() > 1 && arg.starts_with('-') {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                ci += 1;
                match c {
                    'v' => cli.verbose = cli.verbose.saturating_add(1),
                    'w' => cli.watch = true,
                    'e' => cli.edit = true,
                    'p' => cli.page = true,
                    'h' => return ParseOutcome::Help,
                    'V' => return ParseOutcome::Version,
                    'c' | 't' => {
                        let meta = if c == 'c' { "CONFIG" } else { "TAGS" };
                        let rest: String = chars[ci..].iter().collect();
                        ci = chars.len();
                        let value = if rest.is_empty() {
                            match take_value(None, &args, &mut i) {
                                Some(v) => v,
                                None => {
                                    let long = if c == 'c' { "-c" } else { "-t" };
                                    return ParseOutcome::Error(missing_value_short(long, meta));
                                }
                            }
                        } else {
                            rest.strip_prefix('=').unwrap_or(&rest).to_string()
                        };
                        if c == 'c' {
                            cli.config = value;
                        } else {
                            cli.tags = Some(value);
                        }
                    }
                    other => {
                        return ParseOutcome::Error(unexpected(&format!("-{other}")));
                    }
                }
            }
            continue;
        }
        positional.push(arg);
    }

    if positional.is_empty() {
        return ParseOutcome::Error(missing_required());
    }
    if positional.len() > 2 {
        return ParseOutcome::Error(unexpected_positional(&positional[2]));
    }
    cli.input_folder = positional[0].clone();
    cli.output_folder = positional.get(1).cloned();
    ParseOutcome::Run(cli)
}

fn take_value(inline: Option<String>, args: &[String], i: &mut usize) -> Option<String> {
    if let Some(v) = inline {
        return Some(v);
    }
    if *i < args.len() {
        let v = args[*i].clone();
        *i += 1;
        return Some(v);
    }
    None
}

pub fn bin_name() -> String {
    std::env::args()
        .next()
        .map(|p| {
            std::path::Path::new(&p)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| p.clone())
        })
        .unwrap_or_else(|| "marmite".to_string())
}

fn usage_line() -> String {
    format!(
        "Usage: {} [OPTIONS] <INPUT_FOLDER> [OUTPUT_FOLDER]",
        bin_name()
    )
}

fn missing_required() -> String {
    format!(
        "error: the following required arguments were not provided:\n  <INPUT_FOLDER>\n\nUsage: {} <INPUT_FOLDER> [OUTPUT_FOLDER]\n\nFor more information, try '--help'.\n",
        bin_name()
    )
}

fn unexpected(arg: &str) -> String {
    format!(
        "error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n{}\n\nFor more information, try '--help'.\n",
        usage_line()
    )
}

fn unexpected_positional(arg: &str) -> String {
    format!(
        "error: unexpected argument '{arg}' found\n\n{}\n\nFor more information, try '--help'.\n",
        usage_line()
    )
}

fn missing_value(name: &str, meta: &str) -> String {
    format!(
        "error: a value is required for '--{name} <{meta}>' but none was supplied\n\nFor more information, try '--help'.\n"
    )
}

fn missing_value_short(flag: &str, meta: &str) -> String {
    format!(
        "error: a value is required for '{flag} <{meta}>' but none was supplied\n\nFor more information, try '--help'.\n"
    )
}

fn invalid_bool(name: &str, meta: &str, value: &str) -> String {
    format!(
        "error: invalid value '{value}' for '--{name} <{meta}>'\n  [possible values: true, false]\n\nFor more information, try '--help'.\n"
    )
}

