//! Template parsing: turns Tera-flavoured template source into an AST.

use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    Concat,
    Eq,
    Ne,
    Gt,
    Lt,
    Ge,
    Le,
    And,
    Or,
    In,
    NotIn,
}

#[derive(Debug, Clone)]
pub enum Expr {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Array(Vec<Expr>),
    /// Variable lookup with optional path segments.
    Var(String, Vec<PathSeg>),
    /// Function call: `name(a=1, b=2)`.
    Call(String, Vec<(String, Expr)>),
    Filter(Box<Expr>, String, Vec<(String, Expr)>),
    Test(Box<Expr>, bool, String, Vec<Expr>),
    Bin(BinOp, Box<Expr>, Box<Expr>),
    Not(Box<Expr>),
    Neg(Box<Expr>),
    Super,
}

#[derive(Debug, Clone)]
pub enum PathSeg {
    Field(String),
    Index(Box<Expr>),
}

#[derive(Debug, Clone)]
pub enum Node {
    Text(String),
    Output(Expr),
    If(Vec<(Expr, Vec<Node>)>, Option<Vec<Node>>),
    For {
        key: Option<String>,
        value: String,
        iter: Expr,
        body: Vec<Node>,
        empty: Option<Vec<Node>>,
    },
    Set {
        name: String,
        value: Expr,
        global: bool,
    },
    Include {
        names: Vec<String>,
        ignore_missing: bool,
    },
    Block {
        name: String,
        body: Vec<Node>,
    },
    FilterBlock {
        name: String,
        args: Vec<(String, Expr)>,
        body: Vec<Node>,
    },
    Break,
    Continue,
}

#[derive(Debug)]
pub struct ParseError {
    pub message: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

fn err<T>(message: impl Into<String>) -> Result<T, ParseError> {
    Err(ParseError {
        message: message.into(),
    })
}

pub struct Parsed {
    pub nodes: Vec<Node>,
    pub parent: Option<String>,
    pub blocks: Vec<(String, Vec<Node>)>,
}

/// Raw chunks produced by the lexer.
enum Chunk {
    Text(String),
    Expr(String),
    Tag(String),
}

fn lex(source: &str) -> Result<Vec<Chunk>, ParseError> {
    let bytes: Vec<char> = source.chars().collect();
    let mut chunks: Vec<Chunk> = Vec::new();
    let mut text = String::new();
    let mut i = 0;
    // `trim_next` is set when the previous tag requested right-trim.
    let mut trim_next = false;

    while i < bytes.len() {
        if bytes[i] == '{' && i + 1 < bytes.len() {
            let kind = bytes[i + 1];
            if kind == '{' || kind == '%' || kind == '#' {
                let mut start = i + 2;
                let mut trim_left = false;
                if start < bytes.len() && bytes[start] == '-' {
                    trim_left = true;
                    start += 1;
                }
                let (close_a, close_b) = match kind {
                    '{' => ('}', '}'),
                    '%' => ('%', '}'),
                    _ => ('#', '}'),
                };
                // Find the closing delimiter, honouring quotes in expressions.
                let mut j = start;
                let mut quote: Option<char> = None;
                let mut end = None;
                while j < bytes.len() {
                    let c = bytes[j];
                    match quote {
                        Some(q) => {
                            if c == q {
                                quote = None;
                            }
                        }
                        None => {
                            if kind != '#' && (c == '"' || c == '\'') {
                                quote = Some(c);
                            } else if c == close_a && j + 1 < bytes.len() && bytes[j + 1] == close_b
                            {
                                end = Some(j);
                                break;
                            }
                        }
                    }
                    j += 1;
                }
                let Some(end) = end else {
                    return err(format!(
                        "unclosed template delimiter `{}{}`",
                        bytes[i], bytes[i + 1]
                    ));
                };
                let mut inner_end = end;
                let mut trim_right = false;
                if inner_end > start && bytes[inner_end - 1] == '-' {
                    trim_right = true;
                    inner_end -= 1;
                }
                let inner: String = bytes[start..inner_end].iter().collect();

                if trim_left {
                    let trimmed = text.trim_end();
                    text.truncate(trimmed.len());
                }
                if trim_next {
                    let trimmed = text.trim_start().to_string();
                    text = trimmed;
                    trim_next = false;
                }
                if !text.is_empty() {
                    chunks.push(Chunk::Text(std::mem::take(&mut text)));
                } else {
                    text.clear();
                }
                match kind {
                    '{' => chunks.push(Chunk::Expr(inner.trim().to_string())),
                    '%' => chunks.push(Chunk::Tag(inner.trim().to_string())),
                    _ => {}
                }
                trim_next = trim_right;
                i = end + 2;
                continue;
            }
        }
        text.push(bytes[i]);
        i += 1;
    }
    if trim_next {
        let trimmed = text.trim_start().to_string();
        text = trimmed;
    }
    if !text.is_empty() {
        chunks.push(Chunk::Text(text));
    }
    Ok(chunks)
}

pub fn parse(source: &str) -> Result<Parsed, ParseError> {
    let chunks = lex(source)?;
    let mut parser = ChunkParser {
        chunks,
        pos: 0,
        blocks: Vec::new(),
        parent: None,
    };
    let nodes = parser.parse_until(&[])?;
    Ok(Parsed {
        nodes,
        parent: parser.parent.clone(),
        blocks: parser.blocks.clone(),
    })
}

struct ChunkParser {
    chunks: Vec<Chunk>,
    pos: usize,
    blocks: Vec<(String, Vec<Node>)>,
    parent: Option<String>,
}

impl ChunkParser {
    fn parse_until(&mut self, stop: &[&str]) -> Result<Vec<Node>, ParseError> {
        let mut nodes = Vec::new();
        while self.pos < self.chunks.len() {
            match &self.chunks[self.pos] {
                Chunk::Text(t) => {
                    nodes.push(Node::Text(t.clone()));
                    self.pos += 1;
                }
                Chunk::Expr(e) => {
                    let expr = parse_expr(e)?;
                    nodes.push(Node::Output(expr));
                    self.pos += 1;
                }
                Chunk::Tag(tag) => {
                    let keyword = tag.split_whitespace().next().unwrap_or("").to_string();
                    if stop.contains(&keyword.as_str()) {
                        return Ok(nodes);
                    }
                    let tag = tag.clone();
                    self.pos += 1;
                    self.parse_tag(&keyword, &tag, &mut nodes)?;
                }
            }
        }
        if !stop.is_empty() {
            return err(format!("unexpected end of template, expected {stop:?}"));
        }
        Ok(nodes)
    }

    fn current_keyword(&self) -> Option<String> {
        match self.chunks.get(self.pos) {
            Some(Chunk::Tag(t)) => t.split_whitespace().next().map(|s| s.to_string()),
            _ => None,
        }
    }

    fn current_tag(&self) -> String {
        match self.chunks.get(self.pos) {
            Some(Chunk::Tag(t)) => t.clone(),
            _ => String::new(),
        }
    }

    fn parse_tag(
        &mut self,
        keyword: &str,
        tag: &str,
        nodes: &mut Vec<Node>,
    ) -> Result<(), ParseError> {
        let rest = tag[keyword.len()..].trim().to_string();
        match keyword {
            "extends" => {
                self.parent = Some(unquote_str(&rest));
            }
            "raw" => {
                // `raw` blocks are lexed as ordinary chunks; re-serialise them.
                let mut depth = 1;
                let mut out = String::new();
                while self.pos < self.chunks.len() {
                    match &self.chunks[self.pos] {
                        Chunk::Text(t) => out.push_str(t),
                        Chunk::Expr(e) => {
                            out.push_str("{{ ");
                            out.push_str(e);
                            out.push_str(" }}");
                        }
                        Chunk::Tag(t) => {
                            let kw = t.split_whitespace().next().unwrap_or("");
                            if kw == "endraw" {
                                depth -= 1;
                                if depth == 0 {
                                    self.pos += 1;
                                    break;
                                }
                            } else if kw == "raw" {
                                depth += 1;
                            }
                            out.push_str("{% ");
                            out.push_str(t);
                            out.push_str(" %}");
                        }
                    }
                    self.pos += 1;
                }
                nodes.push(Node::Text(out));
            }
            "if" => {
                let mut branches = Vec::new();
                let mut otherwise = None;
                let mut cond = parse_expr(&rest)?;
                loop {
                    let body = self.parse_until(&["elif", "else", "endif"])?;
                    branches.push((cond.clone(), body));
                    match self.current_keyword().as_deref() {
                        Some("elif") => {
                            let tag = self.current_tag();
                            self.pos += 1;
                            cond = parse_expr(tag["elif".len()..].trim())?;
                        }
                        Some("else") => {
                            self.pos += 1;
                            otherwise = Some(self.parse_until(&["endif"])?);
                            self.pos += 1;
                            break;
                        }
                        Some("endif") => {
                            self.pos += 1;
                            break;
                        }
                        _ => return err("unclosed `if` tag"),
                    }
                }
                nodes.push(Node::If(branches, otherwise));
            }
            "for" => {
                let Some(in_pos) = find_keyword(&rest, "in") else {
                    return err(format!("invalid `for` tag: {rest}"));
                };
                let names = rest[..in_pos].trim();
                let iter_src = rest[in_pos + 2..].trim();
                let (key, value) = match names.split_once(',') {
                    Some((k, v)) => (Some(k.trim().to_string()), v.trim().to_string()),
                    None => (None, names.to_string()),
                };
                let iter = parse_expr(iter_src)?;
                let body = self.parse_until(&["else", "endfor"])?;
                let mut empty = None;
                match self.current_keyword().as_deref() {
                    Some("else") => {
                        self.pos += 1;
                        empty = Some(self.parse_until(&["endfor"])?);
                        self.pos += 1;
                    }
                    Some("endfor") => self.pos += 1,
                    _ => return err("unclosed `for` tag"),
                }
                nodes.push(Node::For {
                    key,
                    value,
                    iter,
                    body,
                    empty,
                });
            }
            "set" | "set_global" => {
                let Some((name, value)) = rest.split_once('=') else {
                    return err(format!("invalid `set` tag: {rest}"));
                };
                nodes.push(Node::Set {
                    name: name.trim().to_string(),
                    value: parse_expr(value.trim())?,
                    global: keyword == "set_global",
                });
            }
            "include" => {
                let mut ignore_missing = false;
                let mut spec = rest.clone();
                if let Some(stripped) = spec.strip_suffix("ignore missing") {
                    ignore_missing = true;
                    spec = stripped.trim().to_string();
                }
                let names = if spec.trim_start().starts_with('[') {
                    let inner = spec.trim().trim_start_matches('[').trim_end_matches(']');
                    inner
                        .split(',')
                        .map(|s| unquote_str(s.trim()))
                        .filter(|s| !s.is_empty())
                        .collect()
                } else {
                    vec![unquote_str(spec.trim())]
                };
                nodes.push(Node::Include {
                    names,
                    ignore_missing,
                });
            }
            "block" => {
                let name = rest.trim().to_string();
                let body = self.parse_until(&["endblock"])?;
                self.pos += 1;
                self.blocks.push((name.clone(), body.clone()));
                nodes.push(Node::Block { name, body });
            }
            "filter" => {
                let (name, args) = parse_filter_spec(&rest)?;
                let body = self.parse_until(&["endfilter"])?;
                self.pos += 1;
                nodes.push(Node::FilterBlock { name, args, body });
            }
            "break" => nodes.push(Node::Break),
            "continue" => nodes.push(Node::Continue),
            other => return err(format!("unknown template tag `{other}`")),
        }
        Ok(())
    }
}

fn find_keyword(text: &str, keyword: &str) -> Option<usize> {
    let bytes = text.as_bytes();
    let kw = keyword.as_bytes();
    let mut i = 0;
    while i + kw.len() <= bytes.len() {
        if &bytes[i..i + kw.len()] == kw {
            let before_ok = i == 0 || bytes[i - 1].is_ascii_whitespace();
            let after = bytes.get(i + kw.len());
            let after_ok = after.map_or(true, |c| c.is_ascii_whitespace());
            if before_ok && after_ok {
                return Some(i);
            }
        }
        i += 1;
    }
    None
}

fn unquote_str(text: &str) -> String {
    let t = text.trim();
    if t.len() >= 2
        && ((t.starts_with('"') && t.ends_with('"')) || (t.starts_with('\'') && t.ends_with('\'')))
    {
        t[1..t.len() - 1].to_string()
    } else {
        t.to_string()
    }
}

fn parse_filter_spec(text: &str) -> Result<(String, Vec<(String, Expr)>), ParseError> {
    let text = text.trim();
    match text.split_once('(') {
        Some((name, args)) => {
            let args = args.trim_end().trim_end_matches(')');
            let parsed = parse_kwargs(args)?;
            Ok((name.trim().to_string(), parsed))
        }
        None => Ok((text.to_string(), Vec::new())),
    }
}

fn parse_kwargs(src: &str) -> Result<Vec<(String, Expr)>, ParseError> {
    let mut out = Vec::new();
    for part in split_top_level(src, ',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        match split_kwarg(part) {
            Some((name, value)) => out.push((name, parse_expr(&value)?)),
            None => out.push((String::new(), parse_expr(part)?)),
        }
    }
    Ok(out)
}

/// Split on the first top-level `=` that is not part of `==`, `!=`, `>=`, `<=`.
fn split_kwarg(part: &str) -> Option<(String, String)> {
    let bytes = part.as_bytes();
    let mut depth = 0usize;
    let mut quote: Option<u8> = None;
    for (i, &c) in bytes.iter().enumerate() {
        match quote {
            Some(q) => {
                if c == q {
                    quote = None;
                }
            }
            None => match c {
                b'"' | b'\'' => quote = Some(c),
                b'(' | b'[' => depth += 1,
                b')' | b']' => depth = depth.saturating_sub(1),
                b'=' if depth == 0 => {
                    let prev = if i > 0 { bytes[i - 1] } else { b' ' };
                    let next = bytes.get(i + 1).copied().unwrap_or(b' ');
                    if prev == b'=' || prev == b'!' || prev == b'>' || prev == b'<' || next == b'=' {
                        continue;
                    }
                    let name = part[..i].trim();
                    if !name.is_empty()
                        && name
                            .chars()
                            .all(|c| c.is_alphanumeric() || c == '_' || c == '.')
                    {
                        return Some((name.to_string(), part[i + 1..].trim().to_string()));
                    }
                }
                _ => {}
            },
        }
    }
    None
}

fn split_top_level(src: &str, sep: char) -> Vec<String> {
    let mut out = Vec::new();
    let mut depth = 0usize;
    let mut quote: Option<char> = None;
    let mut cur = String::new();
    for c in src.chars() {
        match quote {
            Some(q) => {
                cur.push(c);
                if c == q {
                    quote = None;
                }
            }
            None => match c {
                '"' | '\'' => {
                    quote = Some(c);
                    cur.push(c);
                }
                '(' | '[' => {
                    depth += 1;
                    cur.push(c);
                }
                ')' | ']' => {
                    depth = depth.saturating_sub(1);
                    cur.push(c);
                }
                c if c == sep && depth == 0 => {
                    out.push(std::mem::take(&mut cur));
                }
                c => cur.push(c),
            },
        }
    }
    if !cur.trim().is_empty() || out.is_empty() {
        out.push(cur);
    }
    out
}

// ---------------------------------------------------------------------------
// Expression parsing
// ---------------------------------------------------------------------------

pub fn parse_expr(src: &str) -> Result<Expr, ParseError> {
    let tokens = tokenize(src)?;
    let mut p = ExprParser { tokens, pos: 0 };
    let expr = p.parse_or()?;
    if p.pos != p.tokens.len() {
        return err(format!("unexpected trailing input in expression `{src}`"));
    }
    Ok(expr)
}

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Ident(String),
    Str(String),
    Int(i64),
    Float(f64),
    Op(String),
}

fn tokenize(src: &str) -> Result<Vec<Tok>, ParseError> {
    let chars: Vec<char> = src.chars().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() {
            i += 1;
            continue;
        }
        if c == '"' || c == '\'' {
            let quote = c;
            i += 1;
            let mut s = String::new();
            while i < chars.len() && chars[i] != quote {
                if chars[i] == '\\' && i + 1 < chars.len() {
                    i += 1;
                    match chars[i] {
                        'n' => s.push('\n'),
                        't' => s.push('\t'),
                        'r' => s.push('\r'),
                        other => s.push(other),
                    }
                } else {
                    s.push(chars[i]);
                }
                i += 1;
            }
            if i >= chars.len() {
                return err("unterminated string literal");
            }
            i += 1;
            out.push(Tok::Str(s));
            continue;
        }
        if c.is_ascii_digit() {
            let start = i;
            let mut is_float = false;
            while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
                if chars[i] == '.' {
                    // Only treat as decimal point when followed by a digit.
                    if !(i + 1 < chars.len() && chars[i + 1].is_ascii_digit()) {
                        break;
                    }
                    is_float = true;
                }
                i += 1;
            }
            let text: String = chars[start..i].iter().collect();
            if is_float {
                out.push(Tok::Float(text.parse().map_err(|_| ParseError {
                    message: format!("invalid number `{text}`"),
                })?));
            } else {
                out.push(Tok::Int(text.parse().map_err(|_| ParseError {
                    message: format!("invalid number `{text}`"),
                })?));
            }
            continue;
        }
        if c.is_alphabetic() || c == '_' {
            let start = i;
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            out.push(Tok::Ident(chars[start..i].iter().collect()));
            continue;
        }
        // Operators
        let two: String = chars[i..(i + 2).min(chars.len())].iter().collect();
        if ["==", "!=", ">=", "<="].contains(&two.as_str()) {
            out.push(Tok::Op(two));
            i += 2;
            continue;
        }
        if "+-*/%~|()[].,=<>!".contains(c) {
            out.push(Tok::Op(c.to_string()));
            i += 1;
            continue;
        }
        return err(format!("unexpected character `{c}` in expression"));
    }
    Ok(out)
}

struct ExprParser {
    tokens: Vec<Tok>,
    pos: usize,
}

impl ExprParser {
    fn peek(&self) -> Option<&Tok> {
        self.tokens.get(self.pos)
    }

    fn eat_op(&mut self, op: &str) -> bool {
        if matches!(self.peek(), Some(Tok::Op(o)) if o == op) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn eat_ident(&mut self, name: &str) -> bool {
        if matches!(self.peek(), Some(Tok::Ident(i)) if i == name) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn parse_or(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_and()?;
        while self.eat_ident("or") {
            let rhs = self.parse_and()?;
            lhs = Expr::Bin(BinOp::Or, Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_and(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_not()?;
        while self.eat_ident("and") {
            let rhs = self.parse_not()?;
            lhs = Expr::Bin(BinOp::And, Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_not(&mut self) -> Result<Expr, ParseError> {
        if self.eat_ident("not") {
            let inner = self.parse_not()?;
            return Ok(Expr::Not(Box::new(inner)));
        }
        self.parse_comparison()
    }

    fn parse_comparison(&mut self) -> Result<Expr, ParseError> {
        let lhs = self.parse_concat()?;
        // `is` tests
        if self.eat_ident("is") {
            let negated = self.eat_ident("not");
            let name = match self.peek().cloned() {
                Some(Tok::Ident(n)) => {
                    self.pos += 1;
                    n
                }
                _ => return err("expected a test name after `is`"),
            };
            let mut args = Vec::new();
            if self.eat_op("(") {
                loop {
                    if self.eat_op(")") {
                        break;
                    }
                    args.push(self.parse_or()?);
                    if self.eat_op(",") {
                        continue;
                    }
                    if self.eat_op(")") {
                        break;
                    }
                    return err("expected `)` in test arguments");
                }
            }
            return Ok(Expr::Test(Box::new(lhs), negated, name, args));
        }
        let op = match self.peek() {
            Some(Tok::Op(o)) => match o.as_str() {
                "==" => Some(BinOp::Eq),
                "!=" => Some(BinOp::Ne),
                ">" => Some(BinOp::Gt),
                "<" => Some(BinOp::Lt),
                ">=" => Some(BinOp::Ge),
                "<=" => Some(BinOp::Le),
                _ => None,
            },
            Some(Tok::Ident(i)) if i == "in" => Some(BinOp::In),
            _ => None,
        };
        if let Some(op) = op {
            self.pos += 1;
            let rhs = self.parse_concat()?;
            return Ok(Expr::Bin(op, Box::new(lhs), Box::new(rhs)));
        }
        // `not in`
        if matches!(self.peek(), Some(Tok::Ident(i)) if i == "not")
            && matches!(self.tokens.get(self.pos + 1), Some(Tok::Ident(i)) if i == "in")
        {
            self.pos += 2;
            let rhs = self.parse_concat()?;
            return Ok(Expr::Bin(BinOp::NotIn, Box::new(lhs), Box::new(rhs)));
        }
        Ok(lhs)
    }

    fn parse_concat(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_additive()?;
        while self.eat_op("~") {
            let rhs = self.parse_additive()?;
            lhs = Expr::Bin(BinOp::Concat, Box::new(lhs), Box::new(rhs));
        }
        Ok(lhs)
    }

    fn parse_additive(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_multiplicative()?;
        loop {
            if self.eat_op("+") {
                let rhs = self.parse_multiplicative()?;
                lhs = Expr::Bin(BinOp::Add, Box::new(lhs), Box::new(rhs));
            } else if self.eat_op("-") {
                let rhs = self.parse_multiplicative()?;
                lhs = Expr::Bin(BinOp::Sub, Box::new(lhs), Box::new(rhs));
            } else {
                return Ok(lhs);
            }
        }
    }

    fn parse_multiplicative(&mut self) -> Result<Expr, ParseError> {
        let mut lhs = self.parse_filtered()?;
        loop {
            if self.eat_op("*") {
                let rhs = self.parse_filtered()?;
                lhs = Expr::Bin(BinOp::Mul, Box::new(lhs), Box::new(rhs));
            } else if self.eat_op("/") {
                let rhs = self.parse_filtered()?;
                lhs = Expr::Bin(BinOp::Div, Box::new(lhs), Box::new(rhs));
            } else if self.eat_op("%") {
                let rhs = self.parse_filtered()?;
                lhs = Expr::Bin(BinOp::Mod, Box::new(lhs), Box::new(rhs));
            } else {
                return Ok(lhs);
            }
        }
    }

    fn parse_filtered(&mut self) -> Result<Expr, ParseError> {
        let mut expr = self.parse_unary()?;
        while self.eat_op("|") {
            let name = match self.peek().cloned() {
                Some(Tok::Ident(n)) => {
                    self.pos += 1;
                    n
                }
                _ => return err("expected a filter name after `|`"),
            };
            let mut args = Vec::new();
            if self.eat_op("(") {
                args = self.parse_call_args()?;
            }
            expr = Expr::Filter(Box::new(expr), name, args);
        }
        Ok(expr)
    }

    fn parse_call_args(&mut self) -> Result<Vec<(String, Expr)>, ParseError> {
        let mut args = Vec::new();
        loop {
            if self.eat_op(")") {
                break;
            }
            // `name=value` or positional
            let mut name = String::new();
            if let (Some(Tok::Ident(id)), Some(Tok::Op(eq))) =
                (self.tokens.get(self.pos), self.tokens.get(self.pos + 1))
            {
                if eq == "=" {
                    name = id.clone();
                    self.pos += 2;
                }
            }
            let value = self.parse_or()?;
            args.push((name, value));
            if self.eat_op(",") {
                continue;
            }
            if self.eat_op(")") {
                break;
            }
            return err("expected `)` in argument list");
        }
        Ok(args)
    }

    fn parse_unary(&mut self) -> Result<Expr, ParseError> {
        if self.eat_op("-") {
            let inner = self.parse_unary()?;
            return Ok(Expr::Neg(Box::new(inner)));
        }
        if self.eat_op("+") {
            return self.parse_unary();
        }
        self.parse_postfix()
    }

    fn parse_postfix(&mut self) -> Result<Expr, ParseError> {
        let mut expr = self.parse_primary()?;
        loop {
            if self.eat_op(".") {
                let seg = match self.peek().cloned() {
                    Some(Tok::Ident(name)) => {
                        self.pos += 1;
                        PathSeg::Field(name)
                    }
                    Some(Tok::Int(idx)) => {
                        self.pos += 1;
                        PathSeg::Field(idx.to_string())
                    }
                    Some(Tok::Float(f)) => {
                        // `a.0.1` tokenises as a float; split it back apart.
                        self.pos += 1;
                        let text = crate::value::format_float(f);
                        let mut segs: Vec<PathSeg> = Vec::new();
                        for part in format!("{f}").split('.') {
                            segs.push(PathSeg::Field(part.to_string()));
                        }
                        let _ = text;
                        expr = push_path(expr, segs);
                        continue;
                    }
                    _ => return err("expected a field name after `.`"),
                };
                expr = push_path(expr, vec![seg]);
                continue;
            }
            if self.eat_op("[") {
                let idx = self.parse_or()?;
                if !self.eat_op("]") {
                    return err("expected `]`");
                }
                expr = push_path(expr, vec![PathSeg::Index(Box::new(idx))]);
                continue;
            }
            return Ok(expr);
        }
    }

    fn parse_primary(&mut self) -> Result<Expr, ParseError> {
        match self.peek().cloned() {
            Some(Tok::Str(s)) => {
                self.pos += 1;
                Ok(Expr::Str(s))
            }
            Some(Tok::Int(i)) => {
                self.pos += 1;
                Ok(Expr::Int(i))
            }
            Some(Tok::Float(f)) => {
                self.pos += 1;
                Ok(Expr::Float(f))
            }
            Some(Tok::Op(op)) if op == "(" => {
                self.pos += 1;
                let inner = self.parse_or()?;
                if !self.eat_op(")") {
                    return err("expected `)`");
                }
                Ok(inner)
            }
            Some(Tok::Op(op)) if op == "[" => {
                self.pos += 1;
                let mut items = Vec::new();
                loop {
                    if self.eat_op("]") {
                        break;
                    }
                    items.push(self.parse_or()?);
                    if self.eat_op(",") {
                        continue;
                    }
                    if self.eat_op("]") {
                        break;
                    }
                    return err("expected `]` in array literal");
                }
                Ok(Expr::Array(items))
            }
            Some(Tok::Op(op)) if op == "!" => {
                self.pos += 1;
                let inner = self.parse_unary()?;
                Ok(Expr::Not(Box::new(inner)))
            }
            Some(Tok::Ident(name)) => {
                self.pos += 1;
                match name.as_str() {
                    "true" | "True" => return Ok(Expr::Bool(true)),
                    "false" | "False" => return Ok(Expr::Bool(false)),
                    _ => {}
                }
                if matches!(self.peek(), Some(Tok::Op(o)) if o == "(") {
                    self.pos += 1;
                    let args = self.parse_call_args()?;
                    if name == "super" {
                        return Ok(Expr::Super);
                    }
                    return Ok(Expr::Call(name, args));
                }
                Ok(Expr::Var(name, Vec::new()))
            }
            other => err(format!("unexpected token in expression: {other:?}")),
        }
    }
}

fn push_path(expr: Expr, segs: Vec<PathSeg>) -> Expr {
    match expr {
        Expr::Var(name, mut path) => {
            path.extend(segs);
            Expr::Var(name, path)
        }
        other => {
            // Attribute access on a non-variable expression: wrap it so the
            // evaluator can still walk the path.
            let mut path = segs;
            let mut expr = other;
            if let Expr::Filter(inner, name, args) = expr {
                expr = Expr::Filter(inner, name, args);
            }
            // Represent as a call to the identity helper with a path.
            Expr::Bin(
                BinOp::In,
                Box::new(Expr::Str(String::new())),
                Box::new(Expr::Array(vec![expr, {
                    let mut v = Vec::new();
                    for seg in path.drain(..) {
                        if let PathSeg::Field(f) = seg {
                            v.push(Expr::Str(f));
                        }
                    }
                    Expr::Array(v)
                }])),
            )
        }
    }
}

