//! Template rendering: context handling, expression evaluation and template
//! inheritance.

use std::collections::HashMap;
use std::fmt;

use super::parse::{BinOp, Expr, Node, Parsed, PathSeg};
use crate::value::{Map, Value};

#[derive(Debug, Clone)]
pub enum Error {
    Undefined(String),
    Message(String),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Undefined(name) => {
                write!(f, "Variable `{name}` not found in context while rendering")
            }
            Error::Message(m) => write!(f, "{m}"),
        }
    }
}

pub fn msg<T>(text: impl Into<String>) -> Result<T, Error> {
    Err(Error::Message(text.into()))
}

pub type FilterFn = Box<dyn Fn(&Value, &Map) -> Result<Value, Error> + Send + Sync>;
pub type FuncFn = Box<dyn Fn(&Map) -> Result<Value, Error> + Send + Sync>;

pub struct Template {
    pub name: String,
    pub nodes: Vec<Node>,
    pub parent: Option<String>,
    pub blocks: HashMap<String, Vec<Node>>,
}

pub struct Engine {
    templates: HashMap<String, Template>,
    filters: HashMap<String, FilterFn>,
    functions: HashMap<String, FuncFn>,
}

impl Engine {
    pub fn new() -> Engine {
        Engine {
            templates: HashMap::new(),
            filters: HashMap::new(),
            functions: HashMap::new(),
        }
    }

    pub fn add_template(&mut self, name: &str, source: &str) -> Result<(), super::parse::ParseError> {
        let Parsed {
            nodes,
            parent,
            blocks,
        } = super::parse::parse(source)?;
        let mut block_map = HashMap::new();
        for (name, body) in blocks {
            block_map.insert(name, body);
        }
        self.templates.insert(
            name.to_string(),
            Template {
                name: name.to_string(),
                nodes,
                parent,
                blocks: block_map,
            },
        );
        Ok(())
    }

    pub fn has_template(&self, name: &str) -> bool {
        self.templates.contains_key(name)
    }

    pub fn template_names(&self) -> Vec<&String> {
        self.templates.keys().collect()
    }

    pub fn register_filter(&mut self, name: &str, f: FilterFn) {
        self.filters.insert(name.to_string(), f);
    }

    pub fn register_function(&mut self, name: &str, f: FuncFn) {
        self.functions.insert(name.to_string(), f);
    }

    pub fn render(&self, name: &str, context: &Map) -> Result<String, Error> {
        let Some(template) = self.templates.get(name) else {
            return msg(format!("Template `{name}` not found"));
        };
        // Build the inheritance chain, most derived first.
        let mut chain: Vec<&Template> = vec![template];
        let mut current = template;
        while let Some(parent_name) = &current.parent {
            let Some(parent) = self.templates.get(parent_name) else {
                return msg(format!(
                    "Template `{}` extends `{parent_name}` which was not found",
                    current.name
                ));
            };
            if chain.iter().any(|t| std::ptr::eq(*t, parent)) {
                return msg("circular template inheritance".to_string());
            }
            chain.push(parent);
            current = parent;
        }
        let mut scopes = vec![context.clone()];
        let mut out = String::new();
        let root = chain[chain.len() - 1];
        let mut state = RenderState {
            engine: self,
            chain: &chain,
            block_depth: HashMap::new(),
        };
        state.render_nodes(&root.nodes, &mut scopes, &mut out)?;
        Ok(out)
    }
}

impl Default for Engine {
    fn default() -> Self {
        Engine::new()
    }
}

struct RenderState<'a> {
    engine: &'a Engine,
    chain: &'a [&'a Template],
    /// For each block name, the index into `chain` currently being rendered,
    /// so `super()` can pick the next definition up the chain.
    block_depth: HashMap<String, usize>,
}

enum Flow {
    Normal,
    Break,
    Continue,
}

impl<'a> RenderState<'a> {
    fn render_nodes(
        &mut self,
        nodes: &[Node],
        scopes: &mut Vec<Map>,
        out: &mut String,
    ) -> Result<Flow, Error> {
        for node in nodes {
            match self.render_node(node, scopes, out)? {
                Flow::Normal => {}
                other => return Ok(other),
            }
        }
        Ok(Flow::Normal)
    }

    fn render_node(
        &mut self,
        node: &Node,
        scopes: &mut Vec<Map>,
        out: &mut String,
    ) -> Result<Flow, Error> {
        match node {
            Node::Text(text) => out.push_str(text),
            Node::Output(expr) => {
                let value = self.eval(expr, scopes)?;
                out.push_str(&value.render());
            }
            Node::If(branches, otherwise) => {
                for (cond, body) in branches {
                    if self.eval_truthy(cond, scopes)? {
                        return self.render_nodes(body, scopes, out);
                    }
                }
                if let Some(body) = otherwise {
                    return self.render_nodes(body, scopes, out);
                }
            }
            Node::For {
                key,
                value,
                iter,
                body,
                empty,
            } => {
                let iterable = match self.eval(iter, scopes) {
                    Ok(v) => v,
                    Err(Error::Undefined(_)) => Value::Null,
                    Err(e) => return Err(e),
                };
                let items: Vec<(Option<Value>, Value)> = match &iterable {
                    Value::Array(items) => items.iter().map(|v| (None, v.clone())).collect(),
                    Value::Map(map) => map
                        .iter()
                        .map(|(k, v)| (Some(Value::Str(k.clone())), v.clone()))
                        .collect(),
                    Value::Str(s) => s
                        .chars()
                        .map(|c| (None, Value::Str(c.to_string())))
                        .collect(),
                    Value::Null => Vec::new(),
                    _ => {
                        return msg("Tried to iterate on a value that is not iterable".to_string())
                    }
                };
                if items.is_empty() {
                    if let Some(body) = empty {
                        return self.render_nodes(body, scopes, out);
                    }
                    return Ok(Flow::Normal);
                }
                let total = items.len();
                for (index, (k, v)) in items.into_iter().enumerate() {
                    let mut frame = Map::new();
                    match (key, k) {
                        (Some(key_name), Some(key_value)) => {
                            frame.insert(key_name.clone(), key_value);
                            frame.insert(value.clone(), v);
                        }
                        (Some(key_name), None) => {
                            // Iterating an array with two names: Tera treats the
                            // first as the index.
                            frame.insert(key_name.clone(), Value::Int(index as i64));
                            frame.insert(value.clone(), v);
                        }
                        (None, Some(key_value)) => {
                            frame.insert(value.clone(), key_value);
                        }
                        (None, None) => {
                            frame.insert(value.clone(), v);
                        }
                    }
                    let mut loop_map = Map::new();
                    loop_map.insert("index", Value::Int(index as i64 + 1));
                    loop_map.insert("index0", Value::Int(index as i64));
                    loop_map.insert("first", Value::Bool(index == 0));
                    loop_map.insert("last", Value::Bool(index + 1 == total));
                    loop_map.insert("length", Value::Int(total as i64));
                    frame.insert("loop", Value::Map(loop_map));
                    scopes.push(frame);
                    let flow = self.render_nodes(body, scopes, out);
                    scopes.pop();
                    match flow? {
                        Flow::Break => break,
                        _ => {}
                    }
                }
            }
            Node::Set {
                name,
                value,
                global,
            } => {
                let v = match self.eval(value, scopes) {
                    Ok(v) => v,
                    Err(Error::Undefined(_)) => Value::Null,
                    Err(e) => return Err(e),
                };
                if *global || scopes.len() == 1 {
                    scopes[0].insert(name.clone(), v);
                } else {
                    let last = scopes.len() - 1;
                    scopes[last].insert(name.clone(), v);
                }
            }
            Node::Include {
                names,
                ignore_missing,
            } => {
                let mut rendered = false;
                for name in names {
                    if self.engine.has_template(name) {
                        let flat = flatten(scopes);
                        let text = self.engine.render(name, &flat)?;
                        out.push_str(&text);
                        rendered = true;
                        break;
                    }
                }
                if !rendered && !ignore_missing {
                    return msg(format!(
                        "Template `{}` not found",
                        names.first().cloned().unwrap_or_default()
                    ));
                }
            }
            Node::Block { name, body } => {
                // Use the most derived definition of this block.
                let start = self.block_depth.get(name).copied().map_or(0, |d| d);
                let (body, level) = self.find_block(name, start).unwrap_or((body, start));
                let previous = self.block_depth.insert(name.clone(), level);
                let flow = self.render_nodes(body, scopes, out);
                match previous {
                    Some(p) => {
                        self.block_depth.insert(name.clone(), p);
                    }
                    None => {
                        self.block_depth.remove(name);
                    }
                }
                return flow;
            }
            Node::FilterBlock { name, args, body } => {
                let mut inner = String::new();
                self.render_nodes(body, scopes, &mut inner)?;
                let kwargs = self.eval_args(args, scopes)?;
                let value = self.apply_filter(name, &Value::Str(inner), &kwargs)?;
                out.push_str(&value.render());
            }
            Node::Break => return Ok(Flow::Break),
            Node::Continue => return Ok(Flow::Continue),
        }
        Ok(Flow::Normal)
    }

    fn find_block(&self, name: &str, from: usize) -> Option<(&'a Vec<Node>, usize)> {
        for (i, template) in self.chain.iter().enumerate().skip(from) {
            if let Some(body) = template.blocks.get(name) {
                return Some((body, i));
            }
        }
        None
    }

    fn render_super(&mut self, scopes: &mut Vec<Map>) -> Result<String, Error> {
        // Find the innermost block currently rendering.
        let Some((name, level)) = self
            .block_depth
            .iter()
            .map(|(k, v)| (k.clone(), *v))
            .max_by_key(|(_, v)| *v)
        else {
            return msg("`super()` called outside of a block".to_string());
        };
        let Some((body, new_level)) = self.find_block(&name, level + 1) else {
            return Ok(String::new());
        };
        let previous = self.block_depth.insert(name.clone(), new_level);
        let mut out = String::new();
        let result = self.render_nodes(body, scopes, &mut out);
        match previous {
            Some(p) => {
                self.block_depth.insert(name, p);
            }
            None => {
                self.block_depth.remove(&name);
            }
        }
        result?;
        Ok(out)
    }

    fn eval_truthy(&mut self, expr: &Expr, scopes: &mut Vec<Map>) -> Result<bool, Error> {
        match self.eval(expr, scopes) {
            Ok(v) => Ok(v.truthy()),
            Err(Error::Undefined(_)) => Ok(false),
            Err(e) => Err(e),
        }
    }

    fn eval_args(
        &mut self,
        args: &[(String, Expr)],
        scopes: &mut Vec<Map>,
    ) -> Result<Map, Error> {
        let mut map = Map::new();
        for (i, (name, expr)) in args.iter().enumerate() {
            let value = match self.eval(expr, scopes) {
                Ok(v) => v,
                Err(Error::Undefined(_)) => Value::Null,
                Err(e) => return Err(e),
            };
            let key = if name.is_empty() {
                format!("__arg{i}")
            } else {
                name.clone()
            };
            map.insert(key, value);
        }
        Ok(map)
    }

    fn eval(&mut self, expr: &Expr, scopes: &mut Vec<Map>) -> Result<Value, Error> {
        match expr {
            Expr::Str(s) => Ok(Value::Str(s.clone())),
            Expr::Int(i) => Ok(Value::Int(*i)),
            Expr::Float(f) => Ok(Value::Float(*f)),
            Expr::Bool(b) => Ok(Value::Bool(*b)),
            Expr::Array(items) => {
                let mut out = Vec::new();
                for item in items {
                    out.push(self.eval(item, scopes)?);
                }
                Ok(Value::Array(out))
            }
            Expr::Super => self.render_super(scopes).map(Value::Str),
            Expr::Var(name, path) => {
                let base = lookup(scopes, name)
                    .ok_or_else(|| Error::Undefined(full_name(name, path)))?;
                walk(&base, path, self, scopes)
                    .ok_or_else(|| Error::Undefined(full_name(name, path)))
            }
            Expr::Field(inner, path) => {
                let base = self.eval(inner, scopes)?;
                walk(&base, path, self, scopes)
                    .ok_or_else(|| Error::Undefined("expression".to_string()))
            }
            Expr::Call(name, args) => {
                let kwargs = self.eval_args(args, scopes)?;
                match self.engine.functions.get(name) {
                    Some(f) => f(&kwargs),
                    None => msg(format!("Function `{name}` was not found")),
                }
            }
            Expr::Filter(inner, name, args) => {
                let value = match self.eval(inner, scopes) {
                    Ok(v) => v,
                    Err(Error::Undefined(var)) => {
                        if name == "default" {
                            let kwargs = self.eval_args(args, scopes)?;
                            return Ok(kwargs.get("value").cloned().unwrap_or(Value::Null));
                        }
                        return Err(Error::Undefined(var));
                    }
                    Err(e) => return Err(e),
                };
                let kwargs = self.eval_args(args, scopes)?;
                self.apply_filter(name, &value, &kwargs)
            }
            Expr::Test(inner, negated, name, args) => {
                let value = match self.eval(inner, scopes) {
                    Ok(v) => Some(v),
                    Err(Error::Undefined(_)) => None,
                    Err(e) => return Err(e),
                };
                let mut params = Vec::new();
                for arg in args {
                    params.push(self.eval(arg, scopes)?);
                }
                let result = super::tests::run(name, value.as_ref(), &params)?;
                Ok(Value::Bool(result != *negated))
            }
            Expr::Not(inner) => {
                let v = self.eval_truthy(inner, scopes)?;
                Ok(Value::Bool(!v))
            }
            Expr::Neg(inner) => {
                let v = self.eval(inner, scopes)?;
                match v {
                    Value::Int(i) => Ok(Value::Int(-i)),
                    Value::Float(f) => Ok(Value::Float(-f)),
                    _ => msg("cannot negate a non-numeric value".to_string()),
                }
            }
            Expr::Bin(op, lhs, rhs) => self.eval_bin(op, lhs, rhs, scopes),
        }
    }

    fn eval_bin(
        &mut self,
        op: &BinOp,
        lhs: &Expr,
        rhs: &Expr,
        scopes: &mut Vec<Map>,
    ) -> Result<Value, Error> {
        match op {
            BinOp::And => {
                let l = self.eval_truthy(lhs, scopes)?;
                if !l {
                    return Ok(Value::Bool(false));
                }
                let r = self.eval_truthy(rhs, scopes)?;
                Ok(Value::Bool(r))
            }
            BinOp::Or => {
                let l = self.eval_truthy(lhs, scopes)?;
                if l {
                    return Ok(Value::Bool(true));
                }
                let r = self.eval_truthy(rhs, scopes)?;
                Ok(Value::Bool(r))
            }
            _ => {
                let l = self.eval_optional(lhs, scopes)?;
                let r = self.eval_optional(rhs, scopes)?;
                match op {
                    BinOp::Concat => {
                        let mut s = concat_part(&l);
                        s.push_str(&concat_part(&r));
                        Ok(Value::Str(s))
                    }
                    BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
                        arithmetic(op, &l, &r)
                    }
                    BinOp::Eq => Ok(Value::Bool(equals(&l, &r))),
                    BinOp::Ne => Ok(Value::Bool(!equals(&l, &r))),
                    BinOp::Gt | BinOp::Lt | BinOp::Ge | BinOp::Le => compare(op, &l, &r),
                    BinOp::In => Ok(Value::Bool(contains(&r, &l))),
                    BinOp::NotIn => Ok(Value::Bool(!contains(&r, &l))),
                    _ => unreachable!(),
                }
            }
        }
    }

    fn eval_optional(&mut self, expr: &Expr, scopes: &mut Vec<Map>) -> Result<Value, Error> {
        match self.eval(expr, scopes) {
            Ok(v) => Ok(v),
            Err(Error::Undefined(_)) => Ok(Value::Null),
            Err(e) => Err(e),
        }
    }

    fn apply_filter(&self, name: &str, value: &Value, args: &Map) -> Result<Value, Error> {
        if let Some(f) = self.engine.filters.get(name) {
            return f(value, args);
        }
        super::filters::apply(name, value, args)
    }
}

fn concat_part(value: &Value) -> String {
    match value {
        Value::Null => String::new(),
        other => other.render(),
    }
}

fn full_name(name: &str, path: &[PathSeg]) -> String {
    let mut out = name.to_string();
    for seg in path {
        match seg {
            PathSeg::Field(f) => {
                out.push('.');
                out.push_str(f);
            }
            PathSeg::Index(_) => out.push_str("[..]"),
        }
    }
    out
}

fn lookup(scopes: &[Map], name: &str) -> Option<Value> {
    for scope in scopes.iter().rev() {
        if let Some(v) = scope.get(name) {
            return Some(v.clone());
        }
    }
    None
}

fn flatten(scopes: &[Map]) -> Map {
    let mut out = Map::new();
    for scope in scopes {
        for (k, v) in scope.iter() {
            out.insert(k.clone(), v.clone());
        }
    }
    out
}

fn walk(
    base: &Value,
    path: &[PathSeg],
    state: &mut RenderState<'_>,
    scopes: &mut Vec<Map>,
) -> Option<Value> {
    let mut current = base.clone();
    for seg in path {
        let key = match seg {
            PathSeg::Field(f) => Value::Str(f.clone()),
            PathSeg::Index(expr) => state.eval(expr, scopes).ok()?,
        };
        current = match (&current, &key) {
            (Value::Map(map), Value::Str(k)) => map.get(k)?.clone(),
            (Value::Array(items), Value::Str(k)) => {
                let idx: usize = k.parse().ok()?;
                items.get(idx)?.clone()
            }
            (Value::Array(items), Value::Int(i)) => {
                let idx = if *i < 0 {
                    (items.len() as i64 + *i) as usize
                } else {
                    *i as usize
                };
                items.get(idx)?.clone()
            }
            (Value::Map(map), Value::Int(i)) => map.get(&i.to_string())?.clone(),
            _ => return None,
        };
    }
    Some(current)
}

fn equals(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(a, b)| equals(a, b))
        }
        (Value::Map(x), Value::Map(y)) => {
            x.len() == y.len()
                && x.iter()
                    .all(|(k, v)| y.get(k).map_or(false, |o| equals(v, o)))
        }
        _ => match (a.as_f64(), b.as_f64()) {
            (Some(x), Some(y)) => x == y,
            _ => false,
        },
    }
}

fn compare(op: &BinOp, a: &Value, b: &Value) -> Result<Value, Error> {
    let ordering = match (a, b) {
        (Value::Str(x), Value::Str(y)) => x.cmp(y),
        _ => match (a.as_f64(), b.as_f64()) {
            (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(std::cmp::Ordering::Equal),
            _ => {
                return msg("cannot compare these values".to_string());
            }
        },
    };
    let result = match op {
        BinOp::Gt => ordering == std::cmp::Ordering::Greater,
        BinOp::Lt => ordering == std::cmp::Ordering::Less,
        BinOp::Ge => ordering != std::cmp::Ordering::Less,
        BinOp::Le => ordering != std::cmp::Ordering::Greater,
        _ => unreachable!(),
    };
    Ok(Value::Bool(result))
}

fn contains(container: &Value, needle: &Value) -> bool {
    match container {
        Value::Array(items) => items.iter().any(|i| equals(i, needle)),
        Value::Map(map) => needle
            .as_str()
            .map_or(false, |k| map.contains_key(k)),
        Value::Str(s) => needle.as_str().map_or(false, |n| s.contains(n)),
        _ => false,
    }
}

fn arithmetic(op: &BinOp, a: &Value, b: &Value) -> Result<Value, Error> {
    let (Some(x), Some(y)) = (a.as_f64(), b.as_f64()) else {
        return msg("cannot perform arithmetic on non-numeric values".to_string());
    };
    let both_int = matches!(a, Value::Int(_)) && matches!(b, Value::Int(_));
    let result = match op {
        BinOp::Add => x + y,
        BinOp::Sub => x - y,
        BinOp::Mul => x * y,
        BinOp::Div => {
            if y == 0.0 {
                return msg("tried to divide by zero".to_string());
            }
            x / y
        }
        BinOp::Mod => {
            if y == 0.0 {
                return msg("tried to divide by zero".to_string());
            }
            x % y
        }
        _ => unreachable!(),
    };
    if both_int && !matches!(op, BinOp::Div) {
        return Ok(Value::Int(result as i64));
    }
    if result == result.trunc() && result.is_finite() {
        // Tera keeps division results as floats but renders them without a
        // trailing `.0`, which `Value::render` already handles.
        return Ok(Value::Float(result));
    }
    Ok(Value::Float(result))
}

