//! Built-in template filters (Tera-compatible).

use super::eval::{msg, Error};
use crate::value::{Map, Value};

fn arg<'a>(args: &'a Map, name: &str) -> Option<&'a Value> {
    args.get(name).or_else(|| args.get("__arg0"))
}

fn arg_str(args: &Map, name: &str) -> Option<String> {
    arg(args, name).map(|v| v.render())
}

fn as_text(value: &Value) -> String {
    value.render()
}

pub fn apply(name: &str, value: &Value, args: &Map) -> Result<Value, Error> {
    match name {
        "safe" => Ok(value.clone()),
        "escape" => Ok(Value::Str(escape_html(&as_text(value)))),
        "escape_xml" => Ok(Value::Str(escape_xml(&as_text(value)))),
        "upper" => Ok(Value::Str(as_text(value).to_uppercase())),
        "lower" => Ok(Value::Str(as_text(value).to_lowercase())),
        "capitalize" => {
            let text = as_text(value);
            let mut chars = text.chars();
            Ok(Value::Str(match chars.next() {
                Some(first) => {
                    first.to_uppercase().collect::<String>() + &chars.as_str().to_lowercase()
                }
                None => String::new(),
            }))
        }
        "title" => Ok(Value::Str(title_case(&as_text(value)))),
        "trim" => Ok(Value::Str(as_text(value).trim().to_string())),
        "trim_start" => Ok(Value::Str(as_text(value).trim_start().to_string())),
        "trim_end" => Ok(Value::Str(as_text(value).trim_end().to_string())),
        "trim_start_matches" => {
            let pat = arg_str(args, "pat").unwrap_or_default();
            let text = as_text(value);
            if pat.is_empty() {
                return Ok(Value::Str(text));
            }
            Ok(Value::Str(text.trim_start_matches(pat.as_str()).to_string()))
        }
        "trim_end_matches" => {
            let pat = arg_str(args, "pat").unwrap_or_default();
            let text = as_text(value);
            if pat.is_empty() {
                return Ok(Value::Str(text));
            }
            Ok(Value::Str(text.trim_end_matches(pat.as_str()).to_string()))
        }
        "replace" => {
            let from = arg_str(args, "from").unwrap_or_default();
            let to = arg_str(args, "to").unwrap_or_default();
            Ok(Value::Str(as_text(value).replace(&from, &to)))
        }
        "truncate" => {
            let length = args
                .get("length")
                .and_then(|v| v.as_int())
                .unwrap_or(255)
                .max(0) as usize;
            let end = args
                .get("end")
                .map(|v| v.render())
                .unwrap_or_else(|| "…".to_string());
            let text = as_text(value);
            let chars: Vec<char> = text.chars().collect();
            if chars.len() <= length {
                Ok(Value::Str(text))
            } else {
                let mut out: String = chars[..length].iter().collect();
                out.push_str(&end);
                Ok(Value::Str(out))
            }
        }
        "striptags" => Ok(Value::Str(strip_tags(&as_text(value)))),
        "spaceless" => Ok(Value::Str(spaceless(&as_text(value)))),
        "linebreaksbr" => Ok(Value::Str(as_text(value).replace('\n', "<br>"))),
        "addslashes" => Ok(Value::Str(
            as_text(value)
                .replace('\\', "\\\\")
                .replace('"', "\\\"")
                .replace('\'', "\\'"),
        )),
        "slugify" => Ok(Value::Str(slugify(&as_text(value)))),
        "length" => Ok(Value::Int(match value {
            Value::Str(s) => s.chars().count() as i64,
            Value::Array(a) => a.len() as i64,
            Value::Map(m) => m.len() as i64,
            Value::Null => 0,
            _ => return msg("filter `length` received an unsupported value".to_string()),
        })),
        "wordcount" => Ok(Value::Int(
            as_text(value).split_whitespace().count() as i64
        )),
        "reverse" => match value {
            Value::Array(items) => {
                let mut out = items.clone();
                out.reverse();
                Ok(Value::Array(out))
            }
            other => Ok(Value::Str(other.render().chars().rev().collect())),
        },
        "first" => match value {
            Value::Array(items) => Ok(items.first().cloned().unwrap_or(Value::Null)),
            Value::Str(s) => Ok(Value::Str(s.chars().next().map(String::from).unwrap_or_default())),
            _ => Ok(Value::Null),
        },
        "last" => match value {
            Value::Array(items) => Ok(items.last().cloned().unwrap_or(Value::Null)),
            Value::Str(s) => Ok(Value::Str(s.chars().last().map(String::from).unwrap_or_default())),
            _ => Ok(Value::Null),
        },
        "nth" => {
            let n = args.get("n").and_then(|v| v.as_int()).unwrap_or(0);
            match value {
                Value::Array(items) => Ok(items.get(n as usize).cloned().unwrap_or(Value::Null)),
                _ => Ok(Value::Null),
            }
        }
        "join" => {
            let sep = args.get("sep").map(|v| v.render()).unwrap_or_default();
            match value {
                Value::Array(items) => Ok(Value::Str(
                    items.iter().map(|v| v.render()).collect::<Vec<_>>().join(&sep),
                )),
                other => Ok(Value::Str(other.render())),
            }
        }
        "split" => {
            let pat = arg_str(args, "pat").unwrap_or_default();
            let text = as_text(value);
            let parts: Vec<Value> = if pat.is_empty() {
                text.chars().map(|c| Value::Str(c.to_string())).collect()
            } else {
                text.split(pat.as_str()).map(|p| Value::str(p)).collect()
            };
            Ok(Value::Array(parts))
        }
        "concat" => {
            let mut items = match value {
                Value::Array(a) => a.clone(),
                other => vec![other.clone()],
            };
            if let Some(with) = args.get("with") {
                match with {
                    Value::Array(more) => items.extend(more.clone()),
                    other => items.push(other.clone()),
                }
            }
            Ok(Value::Array(items))
        }
        "slice" => {
            let items = match value {
                Value::Array(a) => a.clone(),
                Value::Str(s) => {
                    let chars: Vec<char> = s.chars().collect();
                    let (start, end) = slice_bounds(args, chars.len());
                    return Ok(Value::Str(chars[start..end].iter().collect()));
                }
                _ => return Ok(value.clone()),
            };
            let (start, end) = slice_bounds(args, items.len());
            Ok(Value::Array(items[start..end].to_vec()))
        }
        "sort" => {
            let attribute = args.get("attribute").map(|v| v.render());
            let mut items = match value {
                Value::Array(a) => a.clone(),
                _ => return Ok(value.clone()),
            };
            items.sort_by(|a, b| {
                let av = attribute
                    .as_deref()
                    .map_or_else(|| a.clone(), |attr| pick(a, attr));
                let bv = attribute
                    .as_deref()
                    .map_or_else(|| b.clone(), |attr| pick(b, attr));
                compare_values(&av, &bv)
            });
            Ok(Value::Array(items))
        }
        "unique" => {
            let attribute = args.get("attribute").map(|v| v.render());
            let case_sensitive = args
                .get("case_sensitive")
                .and_then(|v| v.as_bool())
                .unwrap_or(false);
            let items = match value {
                Value::Array(a) => a.clone(),
                _ => return Ok(value.clone()),
            };
            let mut seen: Vec<String> = Vec::new();
            let mut out = Vec::new();
            for item in items {
                let key = attribute
                    .as_deref()
                    .map_or_else(|| item.render(), |attr| pick(&item, attr).render());
                let key = if case_sensitive { key } else { key.to_lowercase() };
                if !seen.contains(&key) {
                    seen.push(key);
                    out.push(item);
                }
            }
            Ok(Value::Array(out))
        }
        "filter" => {
            let attribute = args.get("attribute").map(|v| v.render()).unwrap_or_default();
            let expected = args.get("value").cloned().unwrap_or(Value::Null);
            let items = match value {
                Value::Array(a) => a.clone(),
                _ => return Ok(value.clone()),
            };
            let out = items
                .into_iter()
                .filter(|item| {
                    let actual = pick(item, &attribute);
                    actual.render() == expected.render()
                })
                .collect();
            Ok(Value::Array(out))
        }
        "map" => {
            let attribute = args.get("attribute").map(|v| v.render()).unwrap_or_default();
            let items = match value {
                Value::Array(a) => a.clone(),
                _ => return Ok(value.clone()),
            };
            Ok(Value::Array(
                items.iter().map(|item| pick(item, &attribute)).collect(),
            ))
        }
        "group_by" => {
            let attribute = args.get("attribute").map(|v| v.render()).unwrap_or_default();
            let items = match value {
                Value::Array(a) => a.clone(),
                _ => return Ok(value.clone()),
            };
            let mut map = Map::new();
            for item in items {
                let key = pick(&item, &attribute).render();
                match map.get_mut(&key) {
                    Some(Value::Array(list)) => list.push(item),
                    _ => map.insert(key, Value::Array(vec![item])),
                }
            }
            Ok(Value::Map(map))
        }
        "get" => {
            let key = args.get("key").map(|v| v.render()).unwrap_or_default();
            match value {
                Value::Map(map) => Ok(map.get(&key).cloned().unwrap_or(Value::Null)),
                _ => Ok(Value::Null),
            }
        }
        "keys" => match value {
            Value::Map(map) => Ok(Value::Array(
                map.keys().map(|k| Value::Str(k.clone())).collect(),
            )),
            _ => Ok(Value::Array(Vec::new())),
        },
        "values" => match value {
            Value::Map(map) => Ok(Value::Array(map.values().cloned().collect())),
            _ => Ok(Value::Array(Vec::new())),
        },
        "default" => {
            if value.is_null() {
                Ok(args.get("value").cloned().unwrap_or(Value::Null))
            } else {
                Ok(value.clone())
            }
        }
        "int" => {
            let text = as_text(value);
            match value {
                Value::Int(i) => Ok(Value::Int(*i)),
                Value::Float(f) => Ok(Value::Int(*f as i64)),
                Value::Bool(b) => Ok(Value::Int(i64::from(*b))),
                _ => match text.trim().parse::<i64>() {
                    Ok(i) => Ok(Value::Int(i)),
                    Err(_) => match text.trim().parse::<f64>() {
                        Ok(f) => Ok(Value::Int(f as i64)),
                        Err(_) => msg(format!("filter `int` received an invalid value `{text}`")),
                    },
                },
            }
        }
        "float" => match value.as_f64() {
            Some(f) => Ok(Value::Float(f)),
            None => match as_text(value).trim().parse::<f64>() {
                Ok(f) => Ok(Value::Float(f)),
                Err(_) => msg("filter `float` received an invalid value".to_string()),
            },
        },
        "abs" => match value {
            Value::Int(i) => Ok(Value::Int(i.abs())),
            Value::Float(f) => Ok(Value::Float(f.abs())),
            _ => msg("filter `abs` expects a number".to_string()),
        },
        "round" => {
            let method = args.get("method").map(|v| v.render()).unwrap_or_default();
            let precision = args.get("precision").and_then(|v| v.as_int()).unwrap_or(0);
            let Some(number) = value.as_f64() else {
                return msg("filter `round` expects a number".to_string());
            };
            let factor = 10f64.powi(precision as i32);
            let result = match method.as_str() {
                "ceil" => (number * factor).ceil() / factor,
                "floor" => (number * factor).floor() / factor,
                _ => (number * factor).round() / factor,
            };
            if precision == 0 {
                Ok(Value::Float(result))
            } else {
                Ok(Value::Float(result))
            }
        }
        "filesizeformat" => {
            let bytes = value.as_f64().unwrap_or(0.0);
            Ok(Value::Str(filesizeformat(bytes)))
        }
        "pluralize" => {
            let singular = args.get("singular").map(|v| v.render()).unwrap_or_default();
            let plural = args
                .get("plural")
                .map(|v| v.render())
                .unwrap_or_else(|| "s".to_string());
            let n = value.as_f64().unwrap_or(0.0);
            Ok(Value::Str(if (n - 1.0).abs() < f64::EPSILON {
                singular
            } else {
                plural
            }))
        }
        "urlencode" => Ok(Value::Str(urlencode(&as_text(value), b"/"))),
        "urlencode_strict" => Ok(Value::Str(urlencode(&as_text(value), b""))),
        "json_encode" => {
            let pretty = args.get("pretty").and_then(|v| v.as_bool()).unwrap_or(false);
            Ok(Value::Str(if pretty {
                crate::json::to_string_pretty(value)
            } else {
                crate::json::to_string(value)
            }))
        }
        "as_str" => Ok(Value::Str(match value {
            Value::Array(_) | Value::Map(_) => crate::json::to_string(value),
            other => other.render(),
        })),
        "indent" => {
            let prefix = args
                .get("prefix")
                .map(|v| v.render())
                .unwrap_or_else(|| "    ".to_string());
            let first = args.get("first").and_then(|v| v.as_bool()).unwrap_or(false);
            let blank = args.get("blank").and_then(|v| v.as_bool()).unwrap_or(false);
            let text = as_text(value);
            let mut out = String::new();
            for (i, line) in text.split('\n').enumerate() {
                if i > 0 {
                    out.push('\n');
                }
                let should_indent = (i > 0 || first) && (blank || !line.trim().is_empty());
                if should_indent {
                    out.push_str(&prefix);
                }
                out.push_str(line);
            }
            Ok(Value::Str(out))
        }
        "date" => {
            let format = args
                .get("format")
                .map(|v| v.render())
                .unwrap_or_else(|| "%Y-%m-%d".to_string());
            let Some(dt) = crate::content::parse_datetime_value(value) else {
                return msg(format!(
                    "filter `date` received a value it cannot parse: {}",
                    value.render()
                ));
            };
            Ok(Value::Str(dt.format(&format)))
        }
        other => msg(format!("Filter `{other}` not found")),
    }
}

fn slice_bounds(args: &Map, len: usize) -> (usize, usize) {
    let start = args.get("start").and_then(|v| v.as_int()).unwrap_or(0);
    let end = args
        .get("end")
        .and_then(|v| v.as_int())
        .unwrap_or(len as i64);
    let norm = |v: i64| -> usize {
        if v < 0 {
            (len as i64 + v).max(0) as usize
        } else {
            (v as usize).min(len)
        }
    };
    let s = norm(start);
    let e = norm(end).max(s);
    (s, e.min(len))
}

fn pick(value: &Value, attribute: &str) -> Value {
    let mut current = value.clone();
    for part in attribute.split('.') {
        current = match &current {
            Value::Map(map) => map.get(part).cloned().unwrap_or(Value::Null),
            Value::Array(items) => part
                .parse::<usize>()
                .ok()
                .and_then(|i| items.get(i).cloned())
                .unwrap_or(Value::Null),
            _ => Value::Null,
        };
    }
    current
}

fn compare_values(a: &Value, b: &Value) -> std::cmp::Ordering {
    match (a, b) {
        (Value::Str(x), Value::Str(y)) => x.cmp(y),
        _ => match (a.as_f64(), b.as_f64()) {
            (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(std::cmp::Ordering::Equal),
            _ => a.render().cmp(&b.render()),
        },
    }
}

pub fn escape_html(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#x27;"),
            '/' => out.push_str("&#x2F;"),
            c => out.push(c),
        }
    }
    out
}

pub fn escape_xml(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&apos;"),
            c => out.push(c),
        }
    }
    out
}

pub fn strip_tags(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut depth = 0usize;
    for c in text.chars() {
        match c {
            '<' => depth += 1,
            '>' => depth = depth.saturating_sub(1),
            c if depth == 0 => out.push(c),
            _ => {}
        }
    }
    out
}

fn spaceless(text: &str) -> String {
    // Remove whitespace between HTML tags.
    let mut out = String::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '>' {
            out.push('>');
            i += 1;
            let start = i;
            while i < chars.len() && chars[i].is_whitespace() {
                i += 1;
            }
            if i < chars.len() && chars[i] == '<' {
                continue;
            }
            for c in &chars[start..i] {
                out.push(*c);
            }
            continue;
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}

fn title_case(text: &str) -> String {
    let mut out = String::new();
    let mut start_of_word = true;
    for c in text.chars() {
        if c.is_alphanumeric() {
            if start_of_word {
                out.extend(c.to_uppercase());
            } else {
                out.extend(c.to_lowercase());
            }
            start_of_word = false;
        } else {
            out.push(c);
            start_of_word = true;
        }
    }
    out
}

fn filesizeformat(bytes: f64) -> String {
    const UNITS: [&str; 7] = ["bytes", "KB", "MB", "GB", "TB", "PB", "EB"];
    let mut value = bytes;
    let mut unit = 0;
    while value >= 1000.0 && unit < UNITS.len() - 1 {
        value /= 1000.0;
        unit += 1;
    }
    if unit == 0 {
        format!("{} {}", value as i64, UNITS[0])
    } else {
        format!("{:.1} {}", value, UNITS[unit])
    }
}

fn urlencode(text: &str, extra_safe: &[u8]) -> String {
    let mut out = String::new();
    for byte in text.as_bytes() {
        let c = *byte;
        let safe = c.is_ascii_alphanumeric()
            || matches!(c, b'-' | b'_' | b'.' | b'~')
            || extra_safe.contains(&c);
        if safe {
            out.push(c as char);
        } else {
            out.push_str(&format!("%{c:02X}"));
        }
    }
    out
}

/// Reproduces the behaviour of the `slug` crate: transliterate to ASCII,
/// lowercase, and join alphanumeric runs with single dashes.
pub fn slugify(text: &str) -> String {
    let ascii = crate::translit::to_ascii(text);
    let mut out = String::with_capacity(ascii.len());
    let mut pending_dash = false;
    for c in ascii.chars() {
        if c.is_ascii_alphanumeric() {
            if pending_dash && !out.is_empty() {
                out.push('-');
            }
            pending_dash = false;
            out.push(c.to_ascii_lowercase());
        } else {
            pending_dash = true;
        }
    }
    out
}

