use std::path::Path;

use crate::value::{Map, Value};

pub const DEFAULT_FOOTER: &str = "<div>Powered by <a href=\"https://github.com/rochacbruno/marmite\">Marmite</a> | <small><a href=\"https://creativecommons.org/licenses/by-nc-sa/4.0/\">CC-BY_NC-SA</a></small></div>";

/// The literal file written by `--generate-config`. It mirrors the reference's
/// `Default` implementation, which differs from the defaults applied when a key
/// is simply absent from a config file.
