        set("gallery_thumb_size", Value::Int(50));
        set("skip_image_resize", Value::Bool(false));
        Config { data }
    }
}

impl Config {
    pub fn as_map(&self) -> &Map {
        &self.data
    }

    pub fn to_value(&self) -> Value {
        Value::Map(self.data.clone())
    }

    pub fn get(&self, key: &str) -> &Value {
        self.data.get(key).unwrap_or(&Value::Null)
    }

    pub fn set(&mut self, key: &str, value: Value) {
        self.data.insert(key, value);
    }

    pub fn string(&self, key: &str) -> String {
        match self.data.get(key) {
            Some(Value::Str(s)) => s.clone(),
            Some(Value::Null) | None => String::new(),
            Some(other) => other.render(),
        }
    }

    pub fn opt_string(&self, key: &str) -> Option<String> {
        match self.data.get(key) {
            Some(Value::Str(s)) => Some(s.clone()),
            Some(Value::Null) | None => None,
            Some(other) => Some(other.render()),
        }
    }

    pub fn bool(&self, key: &str) -> bool {
        self.data.get(key).and_then(|v| v.as_bool()).unwrap_or(false)
    }

    pub fn int(&self, key: &str) -> i64 {
        self.data.get(key).and_then(|v| v.as_int()).unwrap_or(0)
    }

    /// Merge a parsed YAML/JSON mapping into the configuration.
    pub fn merge(&mut self, value: &Value) {
        if let Value::Map(map) = value {
            for (key, item) in map.iter() {
                self.data.insert(key.clone(), item.clone());
            }
        }
    }

    /// Load a configuration file, returning the defaults when it is missing.
    pub fn load(path: &Path) -> Result<Config, String> {
        let text = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
        let parsed = if path.extension().and_then(|e| e.to_str()) == Some("json") {
            crate::json::parse(&text)?
        } else {
            crate::yaml::parse(&text)?
        };
        let mut config = Config::default();
        config.merge(&parsed);
        Ok(config)
    }

    /// The site URL with any trailing slash removed and the protocol applied.
    pub fn resolved_url(&self) -> String {
        let url = self.string("url");
        if url.is_empty() {
            return String::new();
        }
        let has_protocol = url.starts_with("http://") || url.starts_with("https://");
        if has_protocol {
            return url.trim_end_matches('/').to_string();
        }
        let https = self.data.get("https").and_then(|v| v.as_bool()).unwrap_or(false);
        let scheme = if https { "https" } else { "http" };
        format!("{scheme}://{}", url.trim_end_matches('/'))
    }
}

